-- Adds the 490 new Project Manager vocabulary entries (sort_order 10-499)
-- expanding that word book from 10 to 500 entries, matching
-- src/data/vocabulary/projectManager.json exactly. Does not touch the
-- original 10 rows (sort_order 0-9), which were already inserted by
-- 20260805020000_create_word_books_and_vocabulary_items.sql, and does not
-- modify that migration. No ON CONFLICT clause: a duplicate or conflicting
-- id here means the seed data itself is wrong, so the migration must fail
-- loudly rather than silently skip a row.
insert into public.vocabulary_items (
  id, word_book_id, term, chinese_meaning, part_of_speech, english_definition,
  example_sentence, example_translation, tags, ipa, pronunciation_text, sort_order, is_active
)
values
  ('pm-project-charter', 'project-manager', 'project charter', '项目章程', 'n.', 'A formal document that authorizes a project and defines its objectives and authority.', 'The project charter was signed off by the sponsor before any work began.', '项目发起人在任何工作开始之前签署了项目章程。', ARRAY['planning', 'lifecycle']::text[], null, null, 10, true),
  ('pm-project-initiation', 'project-manager', 'project initiation', '项目启动', 'n.', 'The phase in which a project is formally defined and approved to begin.', 'Project initiation ended once the charter and business case were approved.', '在章程和商业论证获得批准后，项目启动阶段就结束了。', ARRAY['planning', 'lifecycle']::text[], null, null, 11, true),
  ('pm-feasibility-study', 'project-manager', 'feasibility study', '可行性研究', 'n.', 'An assessment of whether a proposed project is practical and worth pursuing.', 'The feasibility study concluded that the new platform would pay for itself within a year.', '可行性研究得出结论，新平台将在一年内收回成本。', ARRAY['planning', 'lifecycle']::text[], null, null, 12, true),
  ('pm-business-case', 'project-manager', 'business case', '商业论证', 'n.', 'A document that justifies a project by weighing its expected costs and benefits.', 'We rewrote the business case after the budget estimate doubled.', '预算估算翻倍后，我们重新撰写了商业论证。', ARRAY['planning', 'lifecycle']::text[], null, null, 13, true),
  ('pm-project-scope-statement', 'project-manager', 'project scope statement', '项目范围说明书', 'n.', 'A document that defines what is and isn''t included in a project.', 'Anything not listed in the project scope statement requires a separate change request.', '任何未列入项目范围说明书的内容都需要单独提交变更请求。', ARRAY['planning', 'lifecycle']::text[], null, null, 14, true),
  ('pm-work-breakdown-structure', 'project-manager', 'work breakdown structure', '工作分解结构', 'n.', 'A hierarchical breakdown of a project''s total scope into manageable pieces of work.', 'We built the work breakdown structure down to tasks that take no more than a week.', '我们把工作分解结构细化到每项任务不超过一周的颗粒度。', ARRAY['planning', 'lifecycle']::text[], null, null, 15, true),
  ('pm-project-baseline', 'project-manager', 'project baseline', '项目基准', 'n.', 'The original approved plan for scope, schedule, and cost, used to measure performance.', 'Actual spending is tracked against the project baseline every month.', '实际支出每个月都会与项目基准进行对比。', ARRAY['planning', 'lifecycle']::text[], null, null, 16, true),
  ('pm-project-closure', 'project-manager', 'project closure', '项目收尾', 'n.', 'The formal process of finishing a project and confirming all deliverables were accepted.', 'Project closure includes a final report and a lessons-learned session.', '项目收尾包括一份总结报告和一次经验教训回顾会议。', ARRAY['planning', 'lifecycle']::text[], null, null, 17, true),
  ('pm-lessons-learned', 'project-manager', 'lessons learned', '经验教训', 'n.', 'Knowledge gained from a project that can improve future work.', 'We captured the lessons learned before the team moved on to the next project.', '在团队投入下一个项目之前，我们记录下了这次的经验教训。', ARRAY['planning', 'lifecycle']::text[], null, null, 18, true),
  ('pm-project-lifecycle', 'project-manager', 'project lifecycle', '项目生命周期', 'n.', 'The series of phases a project passes through from start to finish.', 'Each phase of the project lifecycle ends with a formal review.', '项目生命周期的每个阶段都以一次正式评审结束。', ARRAY['planning', 'lifecycle']::text[], null, null, 19, true),
  ('pm-phase-gate', 'project-manager', 'phase gate', '阶段关口（阶段评审点）', 'n.', 'A checkpoint at the end of a project phase where leadership decides whether to continue.', 'The project stalled at the phase gate because the risk register wasn''t ready.', '由于风险登记册尚未准备好，项目在阶段关口处停滞了。', ARRAY['planning', 'lifecycle']::text[], null, null, 20, true),
  ('pm-project-sponsor', 'project-manager', 'project sponsor', '项目发起人', 'n.', 'The senior person who champions a project and is accountable for its success.', 'The project sponsor stepped in to unblock the budget approval.', '项目发起人出面解决了预算审批的阻塞问题。', ARRAY['planning', 'workplace']::text[], null, null, 21, true),
  ('pm-kickoff-meeting', 'project-manager', 'kickoff meeting', '项目启动会', 'n.', 'The first meeting where a project team and stakeholders align on goals and roles.', 'We scheduled the kickoff meeting for the Monday after the charter was approved.', '我们把项目启动会安排在章程获批后的那个周一。', ARRAY['planning', 'communication']::text[], null, null, 22, true),
  ('pm-project-roadmap', 'project-manager', 'project roadmap', '项目路线图', 'n.', 'A high-level visual summary of a project''s goals and major milestones over time.', 'The product roadmap shows three major releases over the next two quarters.', '产品路线图展示了未来两个季度的三次主要发布。', ARRAY['planning', 'lifecycle']::text[], null, null, 23, true),
  ('pm-project-plan', 'project-manager', 'project plan', '项目计划', 'n.', 'A detailed document describing how a project will be executed, monitored, and closed.', 'The project plan was updated after the client requested an earlier launch date.', '客户要求提前上线日期后，项目计划做了更新。', ARRAY['planning', 'lifecycle']::text[], null, null, 24, true),
  ('pm-project-constraints', 'project-manager', 'project constraints', '项目约束条件', 'n.', 'Limitations, such as budget, time, or scope, that a project must operate within.', 'Fixed budget and a hard deadline were the two biggest project constraints.', '固定预算和硬性截止日期是这个项目最大的两个约束条件。', ARRAY['planning', 'lifecycle']::text[], null, null, 25, true),
  ('pm-assumptions-log', 'project-manager', 'assumptions log', '假设日志', 'n.', 'A record of things assumed to be true for planning purposes but not yet confirmed.', 'We added ''vendor API is stable'' to the assumptions log before estimating the timeline.', '在估算时间线之前，我们把"供应商 API 稳定"加入了假设日志。', ARRAY['planning', 'risk']::text[], null, null, 26, true),
  ('pm-project-governance', 'project-manager', 'project governance', '项目治理', 'n.', 'The framework of roles, responsibilities, and decision rights that guides a project.', 'Project governance defines who can approve a scope change without escalation.', '项目治理明确了谁有权在不上报的情况下批准范围变更。', ARRAY['planning', 'governance']::text[], null, null, 27, true),
  ('pm-project-objective', 'project-manager', 'project objective', '项目目标', 'n.', 'A specific, measurable outcome a project is intended to achieve.', 'Reducing checkout time by 30 percent was the project''s primary objective.', '把结账时间缩短 30% 是这个项目的首要目标。', ARRAY['planning', 'lifecycle']::text[], null, null, 28, true),
  ('pm-success-criteria', 'project-manager', 'success criteria', '成功标准', 'n.', 'The specific conditions that must be met for a project to be considered successful.', 'Success criteria included both the launch date and a minimum customer satisfaction score.', '成功标准既包括上线日期，也包括最低客户满意度分数。', ARRAY['planning', 'lifecycle']::text[], null, null, 29, true),
  ('pm-project-execution', 'project-manager', 'project execution', '项目执行', 'n.', 'The phase where the project plan is carried out and deliverables are produced.', 'Project execution took twice as long as planning because of scope changes.', '由于范围变更，项目执行花的时间是规划阶段的两倍。', ARRAY['planning', 'lifecycle']::text[], null, null, 30, true),
  ('pm-project-monitoring', 'project-manager', 'project monitoring', '项目监控', 'n.', 'The ongoing tracking of project performance against the plan.', 'Weekly project monitoring caught the schedule slip early enough to recover.', '每周的项目监控及早发现了进度滑坡，还来得及补救。', ARRAY['planning', 'governance']::text[], null, null, 31, true),
  ('pm-project-management-plan', 'project-manager', 'project management plan', '项目管理计划', 'n.', 'The comprehensive document that integrates all subsidiary plans for managing a project.', 'The project management plan bundles the schedule, budget, and communication plan into one document.', '项目管理计划把进度、预算和沟通计划整合进了一份文档。', ARRAY['planning', 'lifecycle']::text[], null, null, 32, true),
  ('pm-deliverable-acceptance', 'project-manager', 'deliverable acceptance', '交付物验收', 'n.', 'The formal confirmation that a deliverable meets agreed requirements.', 'Deliverable acceptance requires sign-off from both the client and QA.', '交付物验收需要客户和质量团队双方的签字确认。', ARRAY['planning', 'quality']::text[], null, null, 33, true),
  ('pm-project-scope', 'project-manager', 'project scope', '项目范围', 'n.', 'The boundaries of what work is included and excluded in a project.', 'Adding a mobile app was outside the original project scope.', '增加一款移动应用不在最初的项目范围之内。', ARRAY['planning', 'lifecycle']::text[], null, null, 34, true),
  ('pm-iterative-planning', 'project-manager', 'iterative planning', '迭代式规划', 'n.', 'Planning in repeated cycles, refining details as more information becomes available.', 'Iterative planning let us adjust the roadmap as user feedback came in.', '迭代式规划让我们能随着用户反馈的到来不断调整路线图。', ARRAY['planning', 'agile']::text[], null, null, 35, true),
  ('pm-rolling-wave-planning', 'project-manager', 'rolling wave planning', '滚动式规划', 'n.', 'Planning near-term work in detail while leaving future work at a high level until it''s clearer.', 'We used rolling wave planning since requirements for phase two weren''t finalized yet.', '由于第二阶段的需求尚未最终确定，我们采用了滚动式规划。', ARRAY['planning', 'lifecycle']::text[], null, null, 36, true),
  ('pm-project-phase', 'project-manager', 'project phase', '项目阶段', 'n.', 'A distinct stage within a project''s lifecycle with its own set of activities.', 'Testing doesn''t start until the development phase is complete.', '测试要等开发阶段完成之后才会开始。', ARRAY['planning', 'lifecycle']::text[], null, null, 37, true),
  ('pm-project-deliverable', 'project-manager', 'project deliverable', '项目交付成果', 'n.', 'Any unique product, service, or result a project is required to produce.', 'The training manual was an unplanned but welcome project deliverable.', '培训手册是一份计划外但很受欢迎的项目交付成果。', ARRAY['planning', 'lifecycle']::text[], null, null, 38, true),
  ('pm-exit-criteria', 'project-manager', 'exit criteria', '退出标准', 'n.', 'The conditions that must be satisfied before a phase or project can be considered complete.', 'Exit criteria for the pilot phase included zero critical bugs for two weeks.', '试点阶段的退出标准包括连续两周零严重缺陷。', ARRAY['planning', 'quality']::text[], null, null, 39, true),
  ('pm-critical-success-factor', 'project-manager', 'critical success factor', '关键成功要素', 'n.', 'A condition essential for a project to achieve its objectives.', 'Executive sponsorship was the critical success factor we underestimated.', '高管的支持是我们低估了的一个关键成功要素。', ARRAY['planning', 'lifecycle']::text[], null, null, 40, true),
  ('pm-project-artifact', 'project-manager', 'project artifact', '项目工件（项目文档产出物）', 'n.', 'Any document or output produced and used during a project.', 'The risk register is just one project artifact we keep updated weekly.', '风险登记册只是我们每周更新的众多项目工件之一。', ARRAY['planning', 'governance']::text[], null, null, 41, true),
  ('pm-program-management', 'project-manager', 'program management', '项目群管理（大型项目管理）', 'n.', 'The coordinated management of multiple related projects to achieve benefits not available individually.', 'Program management ensured the three related projects shared a consistent data model.', '项目群管理确保了三个相关项目共用一致的数据模型。', ARRAY['planning', 'governance']::text[], null, null, 42, true),
  ('pm-portfolio-management', 'project-manager', 'portfolio management', '项目组合管理', 'n.', 'The centralized management of one or more project portfolios to achieve strategic objectives.', 'Portfolio management prioritized this project over two lower-impact initiatives.', '项目组合管理把这个项目的优先级排在了两个影响力较低的项目之前。', ARRAY['planning', 'governance']::text[], null, null, 43, true),
  ('pm-project-methodology', 'project-manager', 'project methodology', '项目方法论', 'n.', 'The set of principles and practices used to plan, execute, and manage a project.', 'We chose a hybrid project methodology, mixing Agile delivery with Waterfall reporting.', '我们选择了一种混合项目方法论，把敏捷交付和瀑布式汇报结合在一起。', ARRAY['planning', 'lifecycle']::text[], null, null, 44, true),
  ('pm-requirements-gathering', 'project-manager', 'requirements gathering', '需求收集', 'n.', 'The process of identifying and documenting stakeholders'' needs for a project.', 'Requirements gathering took three weeks because so many departments were involved.', '由于涉及的部门很多，需求收集花了三周时间。', ARRAY['requirements', 'planning']::text[], null, null, 45, true),
  ('pm-requirements-elicitation', 'project-manager', 'requirements elicitation', '需求引出', 'n.', 'Techniques used to draw out stakeholders'' true needs, not just their stated wants.', 'Interviews and shadowing sessions were the main requirements elicitation techniques we used.', '访谈和跟岗观察是我们主要使用的需求引出方法。', ARRAY['requirements', 'planning']::text[], null, null, 46, true),
  ('pm-functional-requirement', 'project-manager', 'functional requirement', '功能性需求', 'n.', 'A requirement describing what a system must do.', 'Exporting reports as PDF was a functional requirement the client insisted on.', '将报告导出为 PDF 是客户坚持要求的一项功能性需求。', ARRAY['requirements', 'planning']::text[], null, null, 47, true),
  ('pm-non-functional-requirement', 'project-manager', 'non-functional requirement', '非功能性需求', 'n.', 'A requirement describing how a system should perform, such as speed or security.', 'Page load time under two seconds was a key non-functional requirement.', '页面加载时间低于两秒是一项关键的非功能性需求。', ARRAY['requirements', 'planning']::text[], null, null, 48, true),
  ('pm-user-story', 'project-manager', 'user story', '用户故事', 'n.', 'A short, plain-language description of a feature from an end user''s perspective.', 'The team wrote a user story for each way a customer could reset a password.', '团队为客户重置密码的每一种方式都写了一个用户故事。', ARRAY['requirements', 'agile']::text[], null, null, 49, true),
  ('pm-acceptance-criteria', 'project-manager', 'acceptance criteria', '验收标准', 'n.', 'The conditions a deliverable must satisfy to be accepted by stakeholders.', 'The user story wasn''t considered done until it met all of its acceptance criteria.', '这个用户故事要满足所有验收标准之后才算完成。', ARRAY['requirements', 'quality']::text[], null, null, 50, true),
  ('pm-use-case', 'project-manager', 'use case', '用例', 'n.', 'A description of how a user interacts with a system to achieve a goal.', 'We walked through the checkout use case to spot missing edge cases.', '我们过了一遍结账用例，找出了遗漏的边界情况。', ARRAY['requirements', 'planning']::text[], null, null, 51, true),
  ('pm-business-requirement', 'project-manager', 'business requirement', '业务需求', 'n.', 'A high-level need that describes why a project exists from the business''s perspective.', 'The core business requirement was to cut manual data entry by half.', '核心业务需求是将人工数据录入减少一半。', ARRAY['requirements', 'planning']::text[], null, null, 52, true),
  ('pm-stakeholder-requirement', 'project-manager', 'stakeholder requirement', '干系人需求', 'n.', 'A specific need or expectation expressed by a project''s stakeholders.', 'Legal added a stakeholder requirement for an audit trail on every transaction.', '法务部门提出了一项干系人需求，要求每笔交易都有审计记录。', ARRAY['requirements', 'stakeholder']::text[], null, null, 53, true),
  ('pm-requirements-traceability-matrix', 'project-manager', 'requirements traceability matrix', '需求追溯矩阵', 'n.', 'A table that links requirements to their source and to the tests that verify them.', 'The requirements traceability matrix showed which test cases still needed to be written.', '需求追溯矩阵显示了哪些测试用例还有待编写。', ARRAY['requirements', 'quality']::text[], null, null, 54, true),
  ('pm-scope-baseline', 'project-manager', 'scope baseline', '范围基准', 'n.', 'The approved version of the scope statement, WBS, and WBS dictionary used for comparison.', 'Any deviation from the scope baseline must go through change control.', '任何偏离范围基准的情况都必须经过变更控制流程。', ARRAY['scope', 'planning']::text[], null, null, 55, true),
  ('pm-change-request', 'project-manager', 'change request', '变更请求', 'n.', 'A formal proposal to modify a project''s scope, schedule, or budget.', 'The client submitted a change request to add a second language to the app.', '客户提交了一份变更请求，要求为应用增加第二种语言。', ARRAY['change', 'planning']::text[], null, null, 56, true),
  ('pm-change-control-board', 'project-manager', 'change control board', '变更控制委员会', 'n.', 'A group responsible for reviewing and approving or rejecting change requests.', 'The change control board rejected the request because it would delay the launch.', '变更控制委员会否决了这项请求，因为它会延误上线时间。', ARRAY['change', 'governance']::text[], null, null, 57, true),
  ('pm-change-management-process', 'project-manager', 'change management process', '变更管理流程', 'n.', 'The defined steps a project uses to evaluate, approve, and implement changes.', 'Skipping the change management process caused the budget to spiral out of control.', '跳过变更管理流程导致预算失控。', ARRAY['change', 'governance']::text[], null, null, 58, true),
  ('pm-impact-analysis', 'project-manager', 'impact analysis', '影响分析', 'n.', 'An assessment of how a proposed change would affect scope, cost, schedule, or risk.', 'The impact analysis showed the new requirement would add two weeks to the schedule.', '影响分析显示新需求会给进度增加两周时间。', ARRAY['change', 'risk']::text[], null, null, 59, true),
  ('pm-scope-validation', 'project-manager', 'scope validation', '范围确认', 'n.', 'The process of formally accepting completed project deliverables.', 'Scope validation with the client confirmed every deliverable matched what was agreed.', '与客户进行的范围确认核实了每一项交付物都符合约定。', ARRAY['scope', 'quality']::text[], null, null, 60, true),
  ('pm-requirements-sign-off', 'project-manager', 'requirements sign-off', '需求签字确认', 'n.', 'The formal approval of a requirements document by stakeholders.', 'Development couldn''t start until requirements sign-off was received from all departments.', '在获得所有部门的需求签字确认之前，开发工作无法启动。', ARRAY['requirements', 'planning']::text[], null, null, 61, true),
  ('pm-gold-plating', 'project-manager', 'gold plating', '过度镀金（超出需求的额外投入）', 'n.', 'Adding extra features or polish beyond what was requested or required.', 'The developer''s gold plating on the settings screen ate into time meant for core features.', '开发人员在设置页面上的过度镀金占用了本该用于核心功能的时间。', ARRAY['scope', 'risk']::text[], null, null, 62, true),
  ('pm-out-of-scope', 'project-manager', 'out of scope', '范围之外', 'adj.', 'Not included within the agreed boundaries of a project.', 'Custom branding for each region was declared out of scope for phase one.', '每个地区的定制品牌方案在第一阶段被列为范围之外。', ARRAY['scope', 'planning']::text[], null, null, 63, true),
  ('pm-in-scope', 'project-manager', 'in scope', '范围之内', 'adj.', 'Included within the agreed boundaries of a project.', 'Only the web app, not the mobile app, is in scope for this release.', '这次发布只有网页应用在范围之内，移动应用不在其中。', ARRAY['scope', 'planning']::text[], null, null, 64, true),
  ('pm-requirements-walkthrough', 'project-manager', 'requirements walkthrough', '需求走查（需求评审会）', 'n.', 'A structured review session where requirements are examined with stakeholders before development begins.', 'We held a requirements walkthrough with QA before finalizing the sprint scope.', '在最终确定迭代范围之前，我们和质量团队一起进行了一次需求走查。', ARRAY['requirements', 'quality']::text[], null, null, 65, true),
  ('pm-requirement-prioritization', 'project-manager', 'requirement prioritization', '需求优先级排序', 'n.', 'The process of ranking requirements by importance, value, or urgency.', 'Requirement prioritization put the payment flow ahead of the loyalty program.', '需求优先级排序把支付流程排在了积分计划前面。', ARRAY['requirements', 'planning']::text[], null, null, 66, true),
  ('pm-moscow-method', 'project-manager', 'MoSCoW method', 'MoSCoW 优先级法', 'n.', 'A prioritization technique that sorts requirements into Must have, Should have, Could have, and Won''t have.', 'We used the MoSCoW method to trim the launch feature list down to what really mattered.', '我们用 MoSCoW 优先级法把上线功能清单缩减到真正重要的部分。', ARRAY['requirements', 'planning']::text[], null, null, 67, true),
  ('pm-backlog-refinement', 'project-manager', 'backlog refinement', '待办事项梳理', 'n.', 'The ongoing activity of reviewing and detailing backlog items for future sprints.', 'Backlog refinement every Thursday keeps the top items ready for sprint planning.', '每周四的待办事项梳理让排在最前面的条目为迭代规划做好了准备。', ARRAY['agile', 'planning']::text[], null, null, 68, true),
  ('pm-epic', 'project-manager', 'epic', '史诗（大型用户故事）', 'n.', 'A large body of work that can be broken down into smaller user stories.', 'The checkout redesign was an epic that spanned four sprints.', '结账页面重设计是一个跨越四个迭代的史诗级任务。', ARRAY['agile', 'requirements']::text[], null, null, 69, true),
  ('pm-user-persona', 'project-manager', 'user persona', '用户画像', 'n.', 'A fictional profile representing a type of user, used to guide product decisions.', 'The user persona for a busy manager shaped how we simplified the approval flow.', '一个繁忙经理的用户画像影响了我们简化审批流程的方式。', ARRAY['requirements', 'planning']::text[], null, null, 70, true),
  ('pm-requirements-freeze', 'project-manager', 'requirements freeze', '需求冻结', 'n.', 'A point after which no new requirements are accepted for the current phase or release.', 'After the requirements freeze, only critical bug fixes were allowed into the release.', '需求冻结之后，只有严重缺陷修复才能被纳入这次发布。', ARRAY['requirements', 'change']::text[], null, null, 71, true),
  ('pm-scope-negotiation', 'project-manager', 'scope negotiation', '范围协商', 'n.', 'Discussions between the project team and stakeholders to agree on what will be delivered.', 'Scope negotiation trimmed three low-value features to protect the launch date.', '范围协商去掉了三个低价值功能，以保住上线日期。', ARRAY['scope', 'communication']::text[], null, null, 72, true),
  ('pm-change-log', 'project-manager', 'change log', '变更日志', 'n.', 'A record of every change made to a project, including who requested it and when.', 'The change log showed the deadline had shifted three times since kickoff.', '变更日志显示截止日期自启动以来已经调整了三次。', ARRAY['change', 'governance']::text[], null, null, 73, true),
  ('pm-minimum-viable-product', 'project-manager', 'minimum viable product', '最小可行产品', 'n.', 'The simplest version of a product that still delivers value and can be tested with real users.', 'We shipped a minimum viable product to gather feedback before building the full feature set.', '我们先发布了一个最小可行产品来收集反馈，然后再开发完整功能。', ARRAY['scope', 'agile']::text[], null, null, 74, true),
  ('pm-requirements-review', 'project-manager', 'requirements review', '需求评审', 'n.', 'A meeting where requirements are examined for completeness, clarity, and feasibility.', 'The requirements review caught a conflict between two departments'' expectations.', '需求评审发现了两个部门之间期望的冲突。', ARRAY['requirements', 'quality']::text[], null, null, 75, true),
  ('pm-business-analyst', 'project-manager', 'business analyst', '业务分析师', 'n.', 'A role responsible for identifying business needs and translating them into requirements.', 'The business analyst mapped the current process before proposing the new one.', '业务分析师先梳理了现有流程，然后才提出新方案。', ARRAY['requirements', 'workplace']::text[], null, null, 76, true),
  ('pm-gap-analysis', 'project-manager', 'gap analysis', '差距分析', 'n.', 'A comparison between current and desired states to identify what needs to change.', 'The gap analysis revealed the team lacked a proper testing environment.', '差距分析发现团队缺少一个合适的测试环境。', ARRAY['requirements', 'planning']::text[], null, null, 77, true),
  ('pm-process-mapping', 'project-manager', 'process mapping', '流程图绘制', 'n.', 'The practice of visually diagramming the steps in a business process.', 'Process mapping the approval workflow exposed three redundant sign-offs.', '对审批工作流进行流程图绘制后，发现了三个多余的签字环节。', ARRAY['requirements', 'planning']::text[], null, null, 78, true),
  ('pm-change-freeze', 'project-manager', 'change freeze', '变更冻结', 'n.', 'A period during which no changes are allowed to be made to a system or plan.', 'We put a change freeze in place the week before the holiday launch.', '在节日上线前一周，我们实施了变更冻结。', ARRAY['change', 'risk']::text[], null, null, 79, true),
  ('pm-gantt-chart', 'project-manager', 'Gantt chart', '甘特图', 'n.', 'A bar chart that shows a project schedule, including task start and end dates.', 'The Gantt chart made it obvious which tasks were running behind.', '甘特图清楚地显示出哪些任务已经落后于计划。', ARRAY['schedule', 'planning']::text[], null, null, 80, true),
  ('pm-critical-path', 'project-manager', 'critical path', '关键路径', 'n.', 'The sequence of dependent tasks that determines the shortest possible project duration.', 'Any delay on the critical path pushes back the entire launch date.', '关键路径上的任何延误都会推迟整体上线日期。', ARRAY['schedule', 'planning']::text[], null, null, 81, true),
  ('pm-task-dependency', 'project-manager', 'task dependency', '任务依赖关系', 'n.', 'A relationship where one task cannot start or finish until another does.', 'We mapped every task dependency before committing to the release date.', '在确定发布日期之前，我们梳理了每一个任务依赖关系。', ARRAY['schedule', 'planning']::text[], null, null, 82, true),
  ('pm-lag-time', 'project-manager', 'lag time', '滞后时间', 'n.', 'A delay intentionally inserted between the end of one task and the start of the next.', 'We added two days of lag time between testing and deployment for a final review.', '我们在测试和部署之间加入了两天的滞后时间，用于最终审查。', ARRAY['schedule', 'planning']::text[], null, null, 83, true),
  ('pm-lead-time', 'project-manager', 'lead time', '提前时间', 'n.', 'The amount of time a successor task is allowed to start before its predecessor finishes.', 'Ordering hardware with a two-week lead time meant it arrived right as development finished.', '硬件订购的提前时间是两周，正好在开发完成时到货。', ARRAY['schedule', 'planning']::text[], null, null, 84, true),
  ('pm-schedule-baseline', 'project-manager', 'schedule baseline', '进度基准', 'n.', 'The originally approved project schedule used to measure actual progress.', 'We are now three weeks behind the schedule baseline.', '我们目前比进度基准晚了三周。', ARRAY['schedule', 'planning']::text[], null, null, 85, true),
  ('pm-schedule-variance', 'project-manager', 'schedule variance', '进度偏差', 'n.', 'The difference between planned progress and actual progress at a given point in time.', 'A negative schedule variance meant the project was falling behind plan.', '进度偏差为负值，说明项目落后于计划。', ARRAY['schedule', 'metrics']::text[], null, null, 86, true),
  ('pm-float-time', 'project-manager', 'float time', '浮动时间（时差）', 'n.', 'The amount of time a task can be delayed without affecting the project finish date.', 'This task has five days of float time, so a short delay won''t hurt the deadline.', '这项任务有五天的浮动时间，短暂延误不会影响截止日期。', ARRAY['schedule', 'planning']::text[], null, null, 87, true),
  ('pm-fast-tracking', 'project-manager', 'fast tracking', '快速跟进（并行赶工）', 'n.', 'Compressing a schedule by running activities in parallel that were originally planned sequentially.', 'Fast tracking design and development in parallel saved us three weeks.', '将设计和开发并行推进的快速跟进方式为我们节省了三周时间。', ARRAY['schedule', 'planning']::text[], null, null, 88, true),
  ('pm-schedule-crashing', 'project-manager', 'schedule crashing', '赶工压缩', 'n.', 'Shortening a schedule by adding resources, usually at a higher cost.', 'Schedule crashing meant hiring two contractors to hit the original deadline.', '赶工压缩意味着要雇佣两名外包人员来赶上最初的截止日期。', ARRAY['schedule', 'planning']::text[], null, null, 89, true),
  ('pm-finish-to-start-dependency', 'project-manager', 'finish-to-start dependency', '结束到开始依赖关系', 'n.', 'A dependency where a task cannot start until its predecessor has finished.', 'Deployment has a finish-to-start dependency on the final QA sign-off.', '部署与最终 QA 签字确认之间是结束到开始依赖关系。', ARRAY['schedule', 'planning']::text[], null, null, 90, true),
  ('pm-start-to-start-dependency', 'project-manager', 'start-to-start dependency', '开始到开始依赖关系', 'n.', 'A dependency where a task cannot start until its predecessor has also started.', 'Content writing has a start-to-start dependency with design, so both begin together.', '内容撰写与设计之间是开始到开始依赖关系，两者同时启动。', ARRAY['schedule', 'planning']::text[], null, null, 91, true),
  ('pm-finish-to-finish-dependency', 'project-manager', 'finish-to-finish dependency', '结束到结束依赖关系', 'n.', 'A dependency where a task cannot finish until its predecessor has also finished.', 'Translation has a finish-to-finish dependency with copy editing.', '翻译与文案校对之间是结束到结束依赖关系。', ARRAY['schedule', 'planning']::text[], null, null, 92, true),
  ('pm-project-deadline', 'project-manager', 'project deadline', '项目截止日期', 'n.', 'The date by which a project or a phase of it must be completed.', 'The project deadline was moved up by two weeks to align with a trade show.', '为了配合一场展会，项目截止日期提前了两周。', ARRAY['schedule', 'planning']::text[], null, null, 93, true),
  ('pm-buffer-time', 'project-manager', 'buffer time', '缓冲时间', 'n.', 'Extra time added to a schedule to absorb unexpected delays.', 'We built in buffer time before the demo in case the integration took longer than planned.', '我们在演示前预留了缓冲时间，以防集成花费的时间超出预期。', ARRAY['schedule', 'risk']::text[], null, null, 94, true),
  ('pm-schedule-compression', 'project-manager', 'schedule compression', '进度压缩', 'n.', 'Techniques used to shorten a project schedule without reducing scope.', 'Schedule compression through fast tracking carried more risk than the team was comfortable with.', '通过快速跟进进行的进度压缩带来的风险超出了团队能接受的范围。', ARRAY['schedule', 'planning']::text[], null, null, 95, true),
  ('pm-duration-estimate', 'project-manager', 'duration estimate', '工期估算', 'n.', 'An approximation of how long an activity will take to complete.', 'The duration estimate for user testing turned out to be far too optimistic.', '用户测试的工期估算结果证明过于乐观。', ARRAY['schedule', 'planning']::text[], null, null, 96, true),
  ('pm-three-point-estimate', 'project-manager', 'three-point estimate', '三点估算法', 'n.', 'An estimating technique that averages optimistic, pessimistic, and most likely durations.', 'The three-point estimate gave a more realistic range than a single guess would have.', '三点估算法给出的范围比单一猜测更贴近实际情况。', ARRAY['schedule', 'planning']::text[], null, null, 97, true),
  ('pm-target-date', 'project-manager', 'target date', '目标日期', 'n.', 'A date the team aims for, which may be more flexible than a hard deadline.', 'March 1st was our target date, with a hard deadline two weeks later.', '3 月 1 日是我们的目标日期，硬性截止日期在两周之后。', ARRAY['schedule', 'planning']::text[], null, null, 98, true),
  ('pm-schedule-slippage', 'project-manager', 'schedule slippage', '进度滑坡', 'n.', 'The gradual falling behind of a project relative to its planned schedule.', 'Small schedule slippage each week added up to a month-long delay by launch.', '每周一点点的进度滑坡累积到上线时已经变成了一个月的延误。', ARRAY['schedule', 'risk']::text[], null, null, 99, true),
  ('pm-delivery-date', 'project-manager', 'delivery date', '交付日期', 'n.', 'The date on which a deliverable is due to be handed over.', 'The vendor missed the agreed delivery date by ten days.', '供应商比约定的交付日期晚了十天。', ARRAY['schedule', 'planning']::text[], null, null, 100, true),
  ('pm-critical-chain', 'project-manager', 'critical chain', '关键链', 'n.', 'A scheduling method that accounts for resource constraints, not just task dependencies.', 'Critical chain scheduling helped us see that one engineer was the real bottleneck.', '关键链排程法让我们看清了一名工程师才是真正的瓶颈所在。', ARRAY['schedule', 'planning']::text[], null, null, 101, true),
  ('pm-resource-leveling', 'project-manager', 'resource leveling', '资源平衡', 'n.', 'Adjusting a schedule to resolve situations where resources are over-allocated.', 'Resource leveling pushed two tasks back a week so no one was double-booked.', '资源平衡把两项任务推后了一周，避免了人员被重复占用。', ARRAY['schedule', 'resources']::text[], null, null, 102, true),
  ('pm-resource-smoothing', 'project-manager', 'resource smoothing', '资源平滑', 'n.', 'Adjusting a schedule within its float to avoid resource peaks without changing the project''s end date.', 'Resource smoothing kept the design team fully utilized without shifting the deadline.', '资源平滑让设计团队保持满负荷工作，同时没有改变截止日期。', ARRAY['schedule', 'resources']::text[], null, null, 103, true),
  ('pm-task-sequencing', 'project-manager', 'task sequencing', '任务排序', 'n.', 'The process of arranging project activities in the order they need to be performed.', 'Correct task sequencing prevented testing from starting before development was done.', '正确的任务排序避免了测试在开发完成之前就开始。', ARRAY['schedule', 'planning']::text[], null, null, 104, true),
  ('pm-network-diagram', 'project-manager', 'network diagram', '网络图', 'n.', 'A visual representation of the logical relationships and sequence among project activities.', 'The network diagram made it easy to spot which tasks had no slack at all.', '网络图让我们很容易看出哪些任务完全没有富余时间。', ARRAY['schedule', 'planning']::text[], null, null, 105, true),
  ('pm-milestone-chart', 'project-manager', 'milestone chart', '里程碑图', 'n.', 'A simplified schedule view that highlights only a project''s key milestones.', 'The milestone chart was the only schedule view executives ever looked at.', '里程碑图是高管们唯一会看的进度视图。', ARRAY['schedule', 'communication']::text[], null, null, 106, true),
  ('pm-project-calendar', 'project-manager', 'project calendar', '项目日历', 'n.', 'A calendar that defines working days and hours available for scheduling project activities.', 'The project calendar excluded public holidays when calculating the deadline.', '项目日历在计算截止日期时排除了法定节假日。', ARRAY['schedule', 'planning']::text[], null, null, 107, true),
  ('pm-schedule-forecast', 'project-manager', 'schedule forecast', '进度预测', 'n.', 'A projection of when a project or phase will actually complete, based on current trends.', 'The schedule forecast showed we''d finish two weeks late if nothing changed.', '进度预测显示，如果情况不变，我们将晚两周完成。', ARRAY['schedule', 'metrics']::text[], null, null, 108, true),
  ('pm-earned-schedule', 'project-manager', 'earned schedule', '挣值进度法', 'n.', 'A technique that converts earned value data into schedule performance measured in time.', 'Earned schedule gave us a clearer picture of the delay than earned value alone.', '挣值进度法比单纯的挣值分析更清楚地展示了延误情况。', ARRAY['schedule', 'metrics']::text[], null, null, 109, true),
  ('pm-work-package', 'project-manager', 'work package', '工作包', 'n.', 'The lowest level of the work breakdown structure, representing an assignable unit of work.', 'Each work package was assigned to a single owner with a clear due date.', '每个工作包都被分配给一名责任人，并有明确的截止日期。', ARRAY['schedule', 'planning']::text[], null, null, 110, true),
  ('pm-predecessor-task', 'project-manager', 'predecessor task', '前置任务', 'n.', 'A task that must be completed or started before another task can proceed.', 'Design was the predecessor task for both development and content writing.', '设计是开发和内容撰写共同的前置任务。', ARRAY['schedule', 'planning']::text[], null, null, 111, true),
  ('pm-successor-task', 'project-manager', 'successor task', '后续任务', 'n.', 'A task that depends on the completion or start of a preceding task.', 'Deployment was the successor task waiting on final QA approval.', '部署是等待最终 QA 批准的后续任务。', ARRAY['schedule', 'planning']::text[], null, null, 112, true),
  ('pm-dependency-mapping', 'project-manager', 'dependency mapping', '依赖关系梳理', 'n.', 'The process of identifying and documenting relationships between tasks or teams.', 'Dependency mapping across three teams revealed a hidden bottleneck in the API team.', '跨三个团队的依赖关系梳理揭示了 API 团队隐藏的瓶颈。', ARRAY['schedule', 'planning']::text[], null, null, 113, true),
  ('pm-time-boxing', 'project-manager', 'time-boxing', '限时法（时间盒）', 'n.', 'Allocating a fixed, maximum amount of time to an activity regardless of the outcome.', 'Time-boxing the design review to one hour kept the discussion focused.', '把设计评审限时在一小时内，让讨论保持了聚焦。', ARRAY['schedule', 'agile']::text[], null, null, 114, true),
  ('pm-project-budget', 'project-manager', 'project budget', '项目预算', 'n.', 'The total approved funding allocated to complete a project.', 'The project budget didn''t account for the extra cloud infrastructure we needed.', '项目预算没有考虑到我们需要的额外云基础设施费用。', ARRAY['budget', 'planning']::text[], null, null, 115, true),
  ('pm-cost-estimate', 'project-manager', 'cost estimate', '成本估算', 'n.', 'An approximation of the monetary resources needed to complete a project or activity.', 'The initial cost estimate was off by nearly 20 percent.', '最初的成本估算与实际情况相差了近 20%。', ARRAY['budget', 'planning']::text[], null, null, 116, true),
  ('pm-cost-overrun', 'project-manager', 'cost overrun', '成本超支', 'n.', 'Spending that exceeds the approved project budget.', 'The cost overrun was traced back to unplanned vendor fees.', '成本超支的原因被追溯到了计划外的供应商费用。', ARRAY['budget', 'risk']::text[], null, null, 117, true),
  ('pm-cost-variance', 'project-manager', 'cost variance', '成本偏差', 'n.', 'The difference between the budgeted cost of work and the actual cost incurred.', 'A positive cost variance meant we were spending less than planned.', '成本偏差为正值，说明我们的实际支出低于计划。', ARRAY['budget', 'metrics']::text[], null, null, 118, true),
  ('pm-earned-value-management', 'project-manager', 'earned value management', '挣值管理', 'n.', 'A technique that measures project performance by comparing planned, earned, and actual value.', 'Earned value management showed the project was both behind schedule and over budget.', '挣值管理显示项目既落后于进度，又超出了预算。', ARRAY['budget', 'metrics']::text[], null, null, 119, true),
  ('pm-actual-cost', 'project-manager', 'actual cost', '实际成本', 'n.', 'The real cost incurred for work completed on a project so far.', 'The actual cost of the pilot phase came in under the estimate.', '试点阶段的实际成本低于估算值。', ARRAY['budget', 'metrics']::text[], null, null, 120, true),
  ('pm-planned-value', 'project-manager', 'planned value', '计划价值', 'n.', 'The authorized budget assigned to scheduled work as of a given point in time.', 'Comparing actual cost to planned value showed we were spending faster than scheduled.', '将实际成本与计划价值对比，显示我们的花费速度快于进度安排。', ARRAY['budget', 'metrics']::text[], null, null, 121, true),
  ('pm-cost-baseline', 'project-manager', 'cost baseline', '成本基准', 'n.', 'The approved, time-phased budget used to measure and monitor cost performance.', 'Every change request now includes its expected impact on the cost baseline.', '现在每份变更请求都要说明其对成本基准的预期影响。', ARRAY['budget', 'planning']::text[], null, null, 122, true),
  ('pm-contingency-reserve', 'project-manager', 'contingency reserve', '应急储备金', 'n.', 'Funds set aside to cover known risks within the approved project scope.', 'We tapped the contingency reserve to cover the unexpected server migration.', '我们动用了应急储备金来支付意外的服务器迁移费用。', ARRAY['budget', 'risk']::text[], null, null, 123, true),
  ('pm-management-reserve', 'project-manager', 'management reserve', '管理储备金', 'n.', 'Funds held back by management to cover unforeseen work outside a project''s known scope.', 'The management reserve was released only after executive approval.', '管理储备金只有在获得高管批准后才会被释放使用。', ARRAY['budget', 'risk']::text[], null, null, 124, true),
  ('pm-return-on-investment', 'project-manager', 'return on investment', '投资回报率', 'n.', 'A measure of the profitability of a project relative to its cost.', 'The automation project had a return on investment of under six months.', '这个自动化项目的投资回报率在六个月以内。', ARRAY['budget', 'metrics']::text[], null, null, 125, true),
  ('pm-total-cost-of-ownership', 'project-manager', 'total cost of ownership', '总拥有成本', 'n.', 'The full cost of a system or solution over its entire lifecycle, not just the purchase price.', 'The cheaper vendor actually had a higher total cost of ownership after support fees.', '算上支持服务费用后，那个更便宜的供应商实际总拥有成本反而更高。', ARRAY['budget', 'metrics']::text[], null, null, 126, true),
  ('pm-burn-rate', 'project-manager', 'burn rate', '消耗速率（资金消耗速度）', 'n.', 'The rate at which a project spends its budget over a given period.', 'Our burn rate meant the budget would run out a month before launch.', '按我们的消耗速率，预算会在上线前一个月就用完。', ARRAY['budget', 'metrics']::text[], null, null, 127, true),
  ('pm-capital-expenditure', 'project-manager', 'capital expenditure', '资本性支出', 'n.', 'Spending on long-term assets, such as equipment or infrastructure.', 'The new servers were booked as capital expenditure rather than an operating cost.', '新服务器被记为资本性支出，而不是运营成本。', ARRAY['budget', 'finance']::text[], null, null, 128, true),
  ('pm-operating-expenditure', 'project-manager', 'operating expenditure', '运营性支出', 'n.', 'Ongoing spending required to run day-to-day operations, such as subscriptions or salaries.', 'Moving to a cloud subscription shifted costs from capital to operating expenditure.', '转向云订阅服务把成本从资本性支出转变成了运营性支出。', ARRAY['budget', 'finance']::text[], null, null, 129, true),
  ('pm-cost-benefit-analysis', 'project-manager', 'cost-benefit analysis', '成本效益分析', 'n.', 'A comparison of the expected costs and benefits of a project or decision.', 'The cost-benefit analysis favored building in-house over buying a third-party tool.', '成本效益分析结果倾向于自研，而不是购买第三方工具。', ARRAY['budget', 'planning']::text[], null, null, 130, true),
  ('pm-resource-plan', 'project-manager', 'resource plan', '资源计划', 'n.', 'A plan that identifies the people, equipment, and materials needed for a project.', 'The resource plan flagged a shortage of QA engineers in the final month.', '资源计划标出了最后一个月质量工程师人手不足的问题。', ARRAY['resources', 'planning']::text[], null, null, 131, true),
  ('pm-resource-pool', 'project-manager', 'resource pool', '资源池', 'n.', 'The group of people and assets available to be assigned to project work.', 'Two designers were pulled from the shared resource pool for the launch push.', '两名设计师从共享资源池中被抽调出来支援上线冲刺。', ARRAY['resources', 'planning']::text[], null, null, 132, true),
  ('pm-resource-constraint', 'project-manager', 'resource constraint', '资源约束', 'n.', 'A limitation on the people, budget, or equipment available for a project.', 'A resource constraint on senior engineers forced us to phase the rollout.', '高级工程师的资源约束迫使我们分阶段推出。', ARRAY['resources', 'planning']::text[], null, null, 133, true),
  ('pm-staffing-plan', 'project-manager', 'staffing plan', '人员配置计划', 'n.', 'A plan that outlines when and how project team members will be brought on and released.', 'The staffing plan added two developers in month two and released them in month five.', '人员配置计划在第二个月增加两名开发人员，并在第五个月将他们释放出去。', ARRAY['resources', 'planning']::text[], null, null, 134, true),
  ('pm-cost-of-delay', 'project-manager', 'cost of delay', '延误成本', 'n.', 'The financial impact of postponing a decision, feature, or project.', 'The cost of delay for the payment feature was estimated at ten thousand dollars a week.', '支付功能的延误成本估计为每周一万美元。', ARRAY['budget', 'metrics']::text[], null, null, 135, true),
  ('pm-budget-forecast', 'project-manager', 'budget forecast', '预算预测', 'n.', 'A projection of expected future spending based on current trends.', 'The budget forecast for next quarter assumed no additional headcount.', '下季度的预算预测假设没有增加人员编制。', ARRAY['budget', 'metrics']::text[], null, null, 136, true),
  ('pm-cost-tracking', 'project-manager', 'cost tracking', '成本跟踪', 'n.', 'The ongoing process of recording and monitoring project expenses.', 'Weekly cost tracking caught the vendor overbilling before it became a bigger problem.', '每周的成本跟踪在问题扩大之前发现了供应商多收费的情况。', ARRAY['budget', 'governance']::text[], null, null, 137, true),
  ('pm-procurement-budget', 'project-manager', 'procurement budget', '采购预算', 'n.', 'The portion of a project budget set aside for purchasing goods or services.', 'The procurement budget covered licenses but not implementation support.', '采购预算涵盖了许可证费用，但不包括实施支持费用。', ARRAY['budget', 'procurement']::text[], null, null, 138, true),
  ('pm-bottom-up-estimating', 'project-manager', 'bottom-up estimating', '自下而上估算法', 'n.', 'Estimating cost or duration by summing estimates for individual work packages.', 'Bottom-up estimating gave a more accurate number than the rough guess we started with.', '自下而上估算法给出的数字比我们最初的粗略猜测更准确。', ARRAY['budget', 'planning']::text[], null, null, 139, true),
  ('pm-top-down-estimating', 'project-manager', 'top-down estimating', '自上而下估算法', 'n.', 'Estimating overall project cost or duration based on similar past projects, then breaking it down.', 'Top-down estimating gave us a quick ballpark before the detailed plan was ready.', '自上而下估算法在详细计划出来之前就给出了一个大致范围。', ARRAY['budget', 'planning']::text[], null, null, 140, true),
  ('pm-parametric-estimating', 'project-manager', 'parametric estimating', '参数估算法', 'n.', 'Using a statistical relationship between historical data and variables to calculate an estimate.', 'Parametric estimating based on lines of code helped size the migration effort.', '基于代码行数的参数估算法帮助我们评估了迁移工作量。', ARRAY['budget', 'planning']::text[], null, null, 141, true),
  ('pm-analogous-estimating', 'project-manager', 'analogous estimating', '类比估算法', 'n.', 'Estimating the cost or duration of a project using data from a similar past project.', 'Analogous estimating from last year''s redesign gave us a rough starting budget.', '类比估算法参考了去年改版项目的数据，给出了初步预算。', ARRAY['budget', 'planning']::text[], null, null, 142, true),
  ('pm-funding-gap', 'project-manager', 'funding gap', '资金缺口', 'n.', 'The difference between the budget required and the funding actually approved.', 'The funding gap forced the team to cut two features from the initial release.', '资金缺口迫使团队从首次发布中砍掉了两个功能。', ARRAY['budget', 'risk']::text[], null, null, 143, true),
  ('pm-resource-capacity', 'project-manager', 'resource capacity', '资源产能', 'n.', 'The maximum amount of work a team or resource can handle in a given period.', 'Resource capacity was the real limit, not the backlog of ideas.', '资源产能才是真正的限制因素，而不是想法储备不够。', ARRAY['resources', 'planning']::text[], null, null, 144, true),
  ('pm-resource-utilization', 'project-manager', 'resource utilization', '资源利用率', 'n.', 'The percentage of available resource capacity actually being used.', 'Resource utilization above 90 percent left no room to absorb urgent requests.', '资源利用率超过 90% 意味着没有余地应对紧急请求。', ARRAY['resources', 'metrics']::text[], null, null, 145, true),
  ('pm-headcount-planning', 'project-manager', 'headcount planning', '人员编制规划', 'n.', 'Forecasting how many people and what roles a project or team will need over time.', 'Headcount planning for next year assumed the team would double.', '明年的人员编制规划假设团队规模将翻倍。', ARRAY['resources', 'planning']::text[], null, null, 146, true),
  ('pm-billable-hours', 'project-manager', 'billable hours', '可计费工时', 'n.', 'Time spent on work that can be charged to a client or project budget.', 'Only billable hours were logged against the client''s project code.', '只有可计费工时才会被记录在客户的项目代码下。', ARRAY['budget', 'workplace']::text[], null, null, 147, true),
  ('pm-budget-approval', 'project-manager', 'budget approval', '预算审批', 'n.', 'The formal authorization to spend a specified amount on a project.', 'Budget approval was delayed a week while finance reviewed the vendor quote.', '预算审批因财务部门审核供应商报价而延迟了一周。', ARRAY['budget', 'governance']::text[], null, null, 148, true),
  ('pm-cost-control', 'project-manager', 'cost control', '成本控制', 'n.', 'The process of monitoring project spending and managing changes to the cost baseline.', 'Strict cost control kept the project within five percent of the original budget.', '严格的成本控制让项目支出保持在原预算的 5% 以内。', ARRAY['budget', 'governance']::text[], null, null, 149, true),
  ('pm-risk-register', 'project-manager', 'risk register', '风险登记册', 'n.', 'A document that lists identified risks along with their owners, impact, and response plans.', 'The risk register is reviewed and updated at the start of every sprint.', '风险登记册在每个迭代开始时都会被审查和更新。', ARRAY['risk', 'governance']::text[], null, null, 150, true),
  ('pm-risk-assessment', 'project-manager', 'risk assessment', '风险评估', 'n.', 'The process of identifying and evaluating potential risks to a project.', 'The risk assessment ranked vendor delay as the top threat to the timeline.', '风险评估把供应商延误列为对进度威胁最大的风险。', ARRAY['risk', 'planning']::text[], null, null, 151, true),
  ('pm-risk-appetite', 'project-manager', 'risk appetite', '风险偏好', 'n.', 'The level of risk an organization is willing to accept in pursuit of its objectives.', 'The company''s low risk appetite ruled out the untested new framework.', '公司较低的风险偏好排除了那个未经验证的新框架。', ARRAY['risk', 'governance']::text[], null, null, 152, true),
  ('pm-risk-tolerance', 'project-manager', 'risk tolerance', '风险承受度', 'n.', 'The specific level of risk variation an organization or stakeholder can withstand.', 'Our risk tolerance for security issues is essentially zero.', '我们对安全问题的风险承受度基本上是零。', ARRAY['risk', 'governance']::text[], null, null, 153, true),
  ('pm-risk-owner', 'project-manager', 'risk owner', '风险负责人', 'n.', 'The person accountable for monitoring a specific risk and executing its response plan.', 'Each risk in the register has a named risk owner, not just a team.', '登记册中的每一项风险都有一个指定的风险负责人，而不只是一个团队。', ARRAY['risk', 'governance']::text[], null, null, 154, true),
  ('pm-risk-trigger', 'project-manager', 'risk trigger', '风险触发条件', 'n.', 'An event or condition that indicates a risk is about to occur or has occurred.', 'A missed vendor milestone was the risk trigger we agreed to watch for.', '供应商错过里程碑就是我们约定要密切关注的风险触发条件。', ARRAY['risk', 'planning']::text[], null, null, 155, true),
  ('pm-contingency-plan', 'project-manager', 'contingency plan', '应急计划', 'n.', 'A predefined set of actions to take if a specific risk occurs.', 'The contingency plan for a vendor outage was to switch to the backup provider.', '针对供应商中断的应急计划是切换到备用供应商。', ARRAY['risk', 'planning']::text[], null, null, 156, true),
  ('pm-issue-log', 'project-manager', 'issue log', '问题日志', 'n.', 'A record of problems that have already occurred and need to be resolved.', 'Every bug reported in production gets logged in the issue log with a priority.', '生产环境中报告的每一个 bug 都会被记录在问题日志中并标注优先级。', ARRAY['risk', 'governance']::text[], null, null, 157, true),
  ('pm-escalation', 'project-manager', 'escalation', '上报', 'n.', 'Raising an issue to a higher level of authority when it cannot be resolved at the current level.', 'Escalation to the sponsor was necessary once the two teams couldn''t agree.', '在两个团队无法达成一致后，就有必要向发起人上报。', ARRAY['risk', 'communication']::text[], null, null, 158, true),
  ('pm-root-cause-analysis', 'project-manager', 'root cause analysis', '根因分析', 'n.', 'A method for identifying the underlying cause of a problem rather than just its symptoms.', 'Root cause analysis traced the outage back to a misconfigured deployment script.', '根因分析将此次中断追溯到了一个配置错误的部署脚本。', ARRAY['risk', 'quality']::text[], null, null, 159, true),
  ('pm-decision-log', 'project-manager', 'decision log', '决策日志', 'n.', 'A record of key project decisions, including who made them and why.', 'The decision log explained why we chose the third-party vendor over building in-house.', '决策日志解释了为什么我们选择了第三方供应商，而不是自研。', ARRAY['decision', 'governance']::text[], null, null, 160, true),
  ('pm-risk-matrix', 'project-manager', 'risk matrix', '风险矩阵', 'n.', 'A visual tool that plots risks by their probability and impact.', 'The risk matrix highlighted three risks in the high-probability, high-impact quadrant.', '风险矩阵突出显示了三项处于高概率、高影响象限的风险。', ARRAY['risk', 'planning']::text[], null, null, 161, true),
  ('pm-probability-and-impact', 'project-manager', 'probability and impact', '概率与影响', 'n.', 'The two dimensions used to assess the significance of a risk.', 'We scored every risk on probability and impact before prioritizing responses.', '在确定应对优先级之前，我们对每项风险都从概率和影响两个维度打了分。', ARRAY['risk', 'planning']::text[], null, null, 162, true),
  ('pm-qualitative-risk-analysis', 'project-manager', 'qualitative risk analysis', '定性风险分析', 'n.', 'Assessing risks by their relative probability and impact using descriptive scales.', 'Qualitative risk analysis sorted risks into high, medium, and low categories.', '定性风险分析把风险分成了高、中、低三个等级。', ARRAY['risk', 'planning']::text[], null, null, 163, true),
  ('pm-quantitative-risk-analysis', 'project-manager', 'quantitative risk analysis', '定量风险分析', 'n.', 'Assessing risks using numerical estimates of probability and monetary impact.', 'Quantitative risk analysis put a dollar figure on the schedule risk.', '定量风险分析为进度风险给出了一个具体的金额数字。', ARRAY['risk', 'planning']::text[], null, null, 164, true),
  ('pm-risk-response-plan', 'project-manager', 'risk response plan', '风险应对计划', 'n.', 'A documented strategy for how a project will address a specific risk.', 'The risk response plan for staff turnover included cross-training two backups.', '针对人员流失的风险应对计划包括对两名后备人员进行交叉培训。', ARRAY['risk', 'planning']::text[], null, null, 165, true),
  ('pm-risk-avoidance', 'project-manager', 'risk avoidance', '风险规避', 'n.', 'A strategy that eliminates a risk by changing the project plan to remove its cause.', 'Risk avoidance meant dropping the untested payment provider entirely.', '风险规避意味着彻底放弃那个未经验证的支付服务商。', ARRAY['risk', 'planning']::text[], null, null, 166, true),
  ('pm-risk-transfer', 'project-manager', 'risk transfer', '风险转移', 'n.', 'Shifting the impact of a risk to a third party, such as through insurance or a contract.', 'Risk transfer through the vendor contract meant they were liable for downtime.', '通过供应商合同进行风险转移，意味着停机责任由他们承担。', ARRAY['risk', 'planning']::text[], null, null, 167, true),
  ('pm-risk-acceptance', 'project-manager', 'risk acceptance', '风险接受', 'n.', 'Acknowledging a risk without taking action to reduce it, usually because its impact is low.', 'Risk acceptance was the right call for a minor, unlikely UI glitch.', '对于一个影响很小、发生概率也不高的界面小问题，风险接受是恰当的选择。', ARRAY['risk', 'planning']::text[], null, null, 168, true),
  ('pm-residual-risk', 'project-manager', 'residual risk', '剩余风险', 'n.', 'The risk that remains after response strategies have been applied.', 'The residual risk after adding a backup server was considered acceptable.', '增加备用服务器之后，剩余风险被认为是可以接受的。', ARRAY['risk', 'planning']::text[], null, null, 169, true),
  ('pm-secondary-risk', 'project-manager', 'secondary risk', '次生风险', 'n.', 'A new risk that arises as a direct result of implementing a risk response.', 'Switching vendors avoided one risk but created a secondary risk around data migration.', '更换供应商规避了一项风险，却带来了数据迁移方面的次生风险。', ARRAY['risk', 'planning']::text[], null, null, 170, true),
  ('pm-single-point-of-failure', 'project-manager', 'single point of failure', '单点故障', 'n.', 'A component whose failure would cause the entire system or project to fail.', 'Having only one person who knew the deployment process was a clear single point of failure.', '只有一个人了解部署流程，这明显是一个单点故障。', ARRAY['risk', 'governance']::text[], null, null, 171, true),
  ('pm-fallback-plan', 'project-manager', 'fallback plan', '备用方案', 'n.', 'An alternative course of action to use if the primary plan fails.', 'The fallback plan was to launch with a manual process if automation wasn''t ready.', '如果自动化流程没能按时就绪，备用方案是先采用人工流程上线。', ARRAY['risk', 'planning']::text[], null, null, 172, true),
  ('pm-decision-matrix', 'project-manager', 'decision matrix', '决策矩阵', 'n.', 'A tool that scores options against weighted criteria to support a decision.', 'The decision matrix made it clear which vendor scored highest on reliability and cost.', '决策矩阵清楚地显示出哪家供应商在可靠性和成本方面得分最高。', ARRAY['decision', 'planning']::text[], null, null, 173, true),
  ('pm-go-no-go-decision', 'project-manager', 'go/no-go decision', '继续/终止决策', 'n.', 'A decision point where leadership decides whether a project should proceed.', 'The go/no-go decision for the launch was made just two days before release.', '上线的继续/终止决策是在发布前两天才做出的。', ARRAY['decision', 'governance']::text[], null, null, 174, true),
  ('pm-issue-escalation-path', 'project-manager', 'issue escalation path', '问题上报路径', 'n.', 'The predefined chain of people to contact as an unresolved issue moves up in urgency.', 'The issue escalation path went from team lead to program manager to sponsor.', '问题上报路径从团队负责人到项目经理，再到发起人。', ARRAY['risk', 'governance']::text[], null, null, 175, true),
  ('pm-risk-workshop', 'project-manager', 'risk workshop', '风险研讨会', 'n.', 'A facilitated session where the team identifies and discusses project risks together.', 'The risk workshop surfaced three risks nobody had mentioned before.', '风险研讨会挖掘出了三项此前从未有人提到过的风险。', ARRAY['risk', 'planning']::text[], null, null, 176, true),
  ('pm-black-swan-event', 'project-manager', 'black swan event', '黑天鹅事件', 'n.', 'A rare, unpredictable event with severe consequences that is obvious only in hindsight.', 'The supplier''s sudden bankruptcy was a black swan event nobody had planned for.', '供应商突然破产是一次谁都没有预料到的黑天鹅事件。', ARRAY['risk', 'planning']::text[], null, null, 177, true),
  ('pm-known-unknown', 'project-manager', 'known unknown', '已知的未知', 'n.', 'A risk or gap that the team is aware exists, even without full details.', 'The final vendor pricing was a known unknown we tracked closely.', '最终的供应商定价是一个我们一直密切关注的已知的未知。', ARRAY['risk', 'planning']::text[], null, null, 178, true),
  ('pm-unknown-unknown', 'project-manager', 'unknown unknown', '未知的未知', 'n.', 'A risk or issue that the team is not even aware could occur.', 'The regulatory change was an unknown unknown that caught the whole industry off guard.', '这项监管变化是一个未知的未知，让整个行业都措手不及。', ARRAY['risk', 'planning']::text[], null, null, 179, true),
  ('pm-risk-threshold', 'project-manager', 'risk threshold', '风险阈值', 'n.', 'The level of risk exposure above which action must be taken.', 'Once the risk score crossed the threshold, it was automatically escalated to the sponsor.', '一旦风险分数超过阈值，就会自动上报给发起人。', ARRAY['risk', 'governance']::text[], null, null, 180, true),
  ('pm-impact-severity', 'project-manager', 'impact severity', '影响严重程度', 'n.', 'A rating of how much damage a risk or issue would cause if it occurred.', 'We rated the impact severity of a data breach as critical.', '我们将数据泄露的影响严重程度评为严重级别。', ARRAY['risk', 'planning']::text[], null, null, 181, true),
  ('pm-watch-list', 'project-manager', 'watch list', '观察清单', 'n.', 'A list of low-priority risks that are monitored but don''t require active response yet.', 'The vendor''s recent layoffs earned them a spot on our watch list.', '供应商最近的裁员让他们进入了我们的观察清单。', ARRAY['risk', 'governance']::text[], null, null, 182, true),
  ('pm-risk-adjusted-backlog', 'project-manager', 'risk-adjusted backlog', '风险调整后待办列表', 'n.', 'A backlog re-ordered to account for the risk associated with each item.', 'The risk-adjusted backlog moved the untested integration to the very first sprint.', '风险调整后待办列表把那个未经测试的集成排到了第一个迭代。', ARRAY['risk', 'agile']::text[], null, null, 183, true),
  ('pm-risk-culture', 'project-manager', 'risk culture', '风险文化', 'n.', 'An organization''s shared attitudes and behaviors toward identifying and managing risk.', 'Encouraging early bad news was part of building a healthy risk culture.', '鼓励尽早汇报坏消息是建立健康风险文化的一部分。', ARRAY['risk', 'governance']::text[], null, null, 184, true),
  ('pm-stakeholder-register', 'project-manager', 'stakeholder register', '干系人登记册', 'n.', 'A document that identifies project stakeholders and their interests, influence, and involvement.', 'The stakeholder register listed twelve people across four departments.', '干系人登记册列出了来自四个部门的十二个人。', ARRAY['stakeholder', 'governance']::text[], null, null, 185, true),
  ('pm-stakeholder-analysis', 'project-manager', 'stakeholder analysis', '干系人分析', 'n.', 'The process of assessing stakeholders'' influence, interest, and expectations.', 'Stakeholder analysis showed the finance team had far more influence than expected.', '干系人分析显示财务团队的影响力远超预期。', ARRAY['stakeholder', 'planning']::text[], null, null, 186, true),
  ('pm-stakeholder-engagement', 'project-manager', 'stakeholder engagement', '干系人参与', 'n.', 'Activities aimed at meeting stakeholder needs and building their support for a project.', 'Regular demos were a key part of our stakeholder engagement strategy.', '定期演示是我们干系人参与策略的重要组成部分。', ARRAY['stakeholder', 'communication']::text[], null, null, 187, true),
  ('pm-communication-plan', 'project-manager', 'communication plan', '沟通计划', 'n.', 'A document that defines what information will be shared, with whom, and how often.', 'The communication plan specified weekly status emails and monthly steering reviews.', '沟通计划规定了每周状态邮件和每月指导委员会评审。', ARRAY['communication', 'planning']::text[], null, null, 188, true),
  ('pm-status-report', 'project-manager', 'status report', '状态报告', 'n.', 'A regular update on project progress, risks, and upcoming work.', 'The status report flagged the vendor delay in red for the third week in a row.', '状态报告已经连续第三周把供应商延误标记为红色。', ARRAY['communication', 'governance']::text[], null, null, 189, true),
  ('pm-executive-summary', 'project-manager', 'executive summary', '执行摘要', 'n.', 'A brief overview at the start of a report that highlights the key points for leadership.', 'The executive summary condensed a forty-page report into three bullet points.', '执行摘要把一份四十页的报告浓缩成了三个要点。', ARRAY['communication', 'governance']::text[], null, null, 190, true),
  ('pm-raci-matrix', 'project-manager', 'RACI matrix', 'RACI 责任分配矩阵', 'n.', 'A chart that defines who is Responsible, Accountable, Consulted, and Informed for each task.', 'The RACI matrix cleared up confusion about who could actually approve the budget.', 'RACI 责任分配矩阵厘清了到底谁有权批准预算的问题。', ARRAY['communication', 'governance']::text[], null, null, 191, true),
  ('pm-power-interest-grid', 'project-manager', 'power/interest grid', '权力/利益方格图', 'n.', 'A tool that maps stakeholders by their level of power and interest in a project.', 'The power/interest grid put the CFO in the manage-closely quadrant.', '权力/利益方格图把首席财务官放在了需要密切管理的象限。', ARRAY['stakeholder', 'planning']::text[], null, null, 192, true),
  ('pm-stakeholder-buy-in', 'project-manager', 'stakeholder buy-in', '干系人认可', 'n.', 'Stakeholders'' agreement to support and commit to a project''s direction.', 'We couldn''t proceed without stakeholder buy-in from both regional offices.', '没有两个地区办公室的干系人认可，我们无法继续推进。', ARRAY['stakeholder', 'communication']::text[], null, null, 193, true),
  ('pm-sponsor-update', 'project-manager', 'sponsor update', '发起人汇报', 'n.', 'A focused briefing given to a project sponsor on progress, risks, and decisions needed.', 'The sponsor update took ten minutes and covered only the three biggest risks.', '发起人汇报只用了十分钟，只涵盖了三项最大的风险。', ARRAY['stakeholder', 'communication']::text[], null, null, 194, true),
  ('pm-steering-committee', 'project-manager', 'steering committee', '指导委员会', 'n.', 'A group of senior stakeholders who provide oversight and make key decisions for a project.', 'The steering committee approved the extra budget after reviewing the business case.', '指导委员会在审阅商业论证后批准了额外预算。', ARRAY['governance', 'communication']::text[], null, null, 195, true),
  ('pm-town-hall-meeting', 'project-manager', 'town hall meeting', '全员大会', 'n.', 'A large, open meeting where leadership shares updates and takes questions from everyone.', 'The town hall meeting was where the reorganization was first announced.', '组织重组的消息最先是在全员大会上宣布的。', ARRAY['communication', 'workplace']::text[], null, null, 196, true),
  ('pm-one-on-one-meeting', 'project-manager', 'one-on-one meeting', '一对一会议', 'n.', 'A private, recurring meeting between a manager and an individual team member.', 'Our weekly one-on-one meeting is where I raise concerns before they become issues.', '我们每周的一对一会议是我在问题恶化之前提出担忧的场合。', ARRAY['communication', 'leadership']::text[], null, null, 197, true),
  ('pm-check-in-meeting', 'project-manager', 'check-in meeting', '例行检查会议', 'n.', 'A short, recurring meeting to review progress and surface blockers.', 'A quick check-in meeting every morning kept the distributed team aligned.', '每天早上的简短例行检查会议让分布式团队保持同步。', ARRAY['communication', 'workplace']::text[], null, null, 198, true),
  ('pm-reporting-transparency', 'project-manager', 'reporting transparency', '汇报透明度', 'n.', 'The practice of sharing accurate project status, including bad news, without spin.', 'Reporting transparency meant the red status stayed red until it was actually fixed.', '汇报透明度意味着红色状态会一直保留，直到问题真正解决。', ARRAY['communication', 'governance']::text[], null, null, 199, true),
  ('pm-active-listening', 'project-manager', 'active listening', '积极倾听', 'n.', 'Fully concentrating on and understanding what a speaker is saying before responding.', 'Active listening during the client call revealed a concern we hadn''t addressed.', '在客户电话会议中的积极倾听发现了一个我们尚未解决的担忧。', ARRAY['communication', 'leadership']::text[], null, null, 200, true),
  ('pm-stakeholder-expectations', 'project-manager', 'stakeholder expectations', '干系人期望', 'n.', 'What stakeholders anticipate or want from a project''s outcome.', 'Managing stakeholder expectations early prevented disappointment at launch.', '及早管理干系人期望，避免了上线时的失望情绪。', ARRAY['stakeholder', 'communication']::text[], null, null, 201, true),
  ('pm-communication-cadence', 'project-manager', 'communication cadence', '沟通节奏', 'n.', 'The regular rhythm and frequency at which project updates are shared.', 'We doubled the communication cadence to daily once the project entered crunch time.', '一旦项目进入冲刺期，我们就把沟通节奏加快到每天一次。', ARRAY['communication', 'planning']::text[], null, null, 202, true),
  ('pm-escalation-matrix', 'project-manager', 'escalation matrix', '上报矩阵', 'n.', 'A table showing who to contact and how quickly, based on the severity of an issue.', 'The escalation matrix specified a one-hour response time for critical outages.', '上报矩阵规定严重中断问题必须在一小时内响应。', ARRAY['communication', 'governance']::text[], null, null, 203, true),
  ('pm-project-newsletter', 'project-manager', 'project newsletter', '项目通讯', 'n.', 'A periodic written update sent to a broad group of stakeholders.', 'The monthly project newsletter kept remote offices in the loop without extra meetings.', '每月的项目通讯让远程办公室在不增加会议的情况下也能了解最新进展。', ARRAY['communication', 'stakeholder']::text[], null, null, 204, true),
  ('pm-progress-update', 'project-manager', 'progress update', '进度更新', 'n.', 'A short summary of what has been accomplished and what remains.', 'The Friday progress update took five minutes and covered every workstream.', '每周五的进度更新只需五分钟，就能涵盖所有工作条线。', ARRAY['communication', 'governance']::text[], null, null, 205, true),
  ('pm-feedback-loop', 'project-manager', 'feedback loop', '反馈闭环', 'n.', 'A process where output or results are used to inform and adjust future actions.', 'A tight feedback loop with users let us fix confusing screens within days.', '与用户之间紧密的反馈闭环让我们能在几天内修复令人困惑的界面。', ARRAY['communication', 'agile']::text[], null, null, 206, true),
  ('pm-information-radiator', 'project-manager', 'information radiator', '信息发射器（可视化看板）', 'n.', 'A prominently displayed chart or board that shows project status at a glance.', 'The information radiator on the office wall showed the burndown chart in real time.', '办公室墙上的信息发射器实时显示着燃尽图。', ARRAY['communication', 'agile']::text[], null, null, 207, true),
  ('pm-project-dashboard', 'project-manager', 'project dashboard', '项目看板', 'n.', 'A visual summary of key project metrics, status, and risks.', 'The project dashboard pulled data automatically instead of relying on manual updates.', '项目看板自动拉取数据，不再依赖人工更新。', ARRAY['communication', 'metrics']::text[], null, null, 208, true),
  ('pm-project-visibility', 'project-manager', 'project visibility', '项目可视性', 'n.', 'The degree to which stakeholders can easily see a project''s current status.', 'Poor project visibility meant leadership was surprised by the delay.', '较差的项目可视性导致高管对延误感到意外。', ARRAY['communication', 'governance']::text[], null, null, 209, true),
  ('pm-cross-team-communication', 'project-manager', 'cross-team communication', '跨团队沟通', 'n.', 'The exchange of information between different teams working toward related goals.', 'Cross-team communication improved once we set up a shared channel for both squads.', '在为两个小组建立共享沟通渠道之后，跨团队沟通有了改善。', ARRAY['communication', 'collaboration']::text[], null, null, 210, true),
  ('pm-informal-communication', 'project-manager', 'informal communication', '非正式沟通', 'n.', 'Casual, unstructured exchanges of information, such as hallway conversations.', 'Some of our best early warnings came from informal communication, not status reports.', '我们最早的一些预警信号来自非正式沟通，而不是状态报告。', ARRAY['communication', 'workplace']::text[], null, null, 211, true),
  ('pm-formal-communication', 'project-manager', 'formal communication', '正式沟通', 'n.', 'Official, structured exchanges of information, such as reports or contracts.', 'Any commitment to the client had to go through formal communication, not a quick chat.', '对客户的任何承诺都必须通过正式沟通，而不是随口一说。', ARRAY['communication', 'workplace']::text[], null, null, 212, true),
  ('pm-communication-channel', 'project-manager', 'communication channel', '沟通渠道', 'n.', 'The medium used to exchange information, such as email, chat, or meetings.', 'We standardized on one communication channel for urgent issues to avoid missed messages.', '我们把紧急问题的沟通渠道统一为一种，以避免消息被遗漏。', ARRAY['communication', 'planning']::text[], null, null, 213, true),
  ('pm-audience-analysis', 'project-manager', 'audience analysis', '受众分析', 'n.', 'Understanding a message''s recipients so it can be tailored to their needs and interests.', 'Audience analysis told us the executive summary needed numbers, not technical jargon.', '受众分析告诉我们，执行摘要需要的是数字，而不是技术术语。', ARRAY['communication', 'planning']::text[], null, null, 214, true),
  ('pm-key-message', 'project-manager', 'key message', '核心信息', 'n.', 'The single most important point a communication is meant to convey.', 'The key message of the update was simple: we are on track for launch.', '这次更新的核心信息很简单：我们的上线进度正常。', ARRAY['communication', 'planning']::text[], null, null, 215, true),
  ('pm-elevator-pitch', 'project-manager', 'elevator pitch', '电梯演讲', 'n.', 'A short, persuasive summary of an idea or project that can be delivered in under a minute.', 'The team practiced their elevator pitch before presenting to the board.', '团队在向董事会汇报之前反复练习了他们的电梯演讲。', ARRAY['communication', 'stakeholder']::text[], null, null, 216, true),
  ('pm-stakeholder-mapping', 'project-manager', 'stakeholder mapping', '干系人图谱绘制', 'n.', 'Visually organizing stakeholders based on their relationships and level of influence.', 'Stakeholder mapping revealed we had been under-engaging a key regional director.', '干系人图谱绘制显示，我们对一位关键的区域总监关注不够。', ARRAY['stakeholder', 'planning']::text[], null, null, 217, true),
  ('pm-consensus-building', 'project-manager', 'consensus building', '达成共识', 'n.', 'The process of working toward general agreement among a group of stakeholders.', 'Consensus building took two extra meetings but avoided conflict later on.', '达成共识多花了两次会议的时间，但避免了后续的冲突。', ARRAY['communication', 'leadership']::text[], null, null, 218, true),
  ('pm-influence-without-authority', 'project-manager', 'influence without authority', '无职权影响力', 'n.', 'The ability to guide outcomes and gain cooperation without formal power over others.', 'The project manager relied on influence without authority to get engineering to prioritize the fix.', '项目经理凭借无职权影响力说服工程团队优先处理了这个修复。', ARRAY['communication', 'leadership']::text[], null, null, 219, true),
  ('pm-scrum-master', 'project-manager', 'Scrum master', 'Scrum 主管', 'n.', 'A role responsible for facilitating Scrum events and removing obstacles for the team.', 'The Scrum master stepped in to resolve a conflict between two teams.', 'Scrum 主管出面解决了两个团队之间的冲突。', ARRAY['agile', 'workplace']::text[], null, null, 220, true),
  ('pm-product-owner', 'project-manager', 'product owner', '产品负责人', 'n.', 'The role responsible for maximizing product value and managing the product backlog.', 'The product owner reprioritized the backlog after a competitor launched a similar feature.', '在竞争对手发布类似功能后，产品负责人重新调整了待办列表的优先级。', ARRAY['agile', 'workplace']::text[], null, null, 221, true),
  ('pm-sprint-planning', 'project-manager', 'sprint planning', '迭代规划会议', 'n.', 'A meeting where the team selects backlog items to work on during the upcoming sprint.', 'Sprint planning ran long because the team debated two conflicting priorities.', '由于团队就两个相互冲突的优先级进行了争论，迭代规划会议开得比较久。', ARRAY['agile', 'planning']::text[], null, null, 222, true),
  ('pm-sprint-review', 'project-manager', 'sprint review', '迭代评审会议', 'n.', 'A meeting at the end of a sprint where the team demonstrates completed work.', 'Stakeholders gave direct feedback during the sprint review.', '干系人在迭代评审会议上给出了直接的反馈。', ARRAY['agile', 'communication']::text[], null, null, 223, true),
  ('pm-sprint-retrospective', 'project-manager', 'sprint retrospective', '迭代回顾会议', 'n.', 'A meeting where the team reflects on the past sprint to identify improvements.', 'The sprint retrospective led to a new rule about writing tests before merging code.', '迭代回顾会议促成了一条新规则：合并代码前必须先写测试。', ARRAY['agile', 'communication']::text[], null, null, 224, true),
  ('pm-daily-standup', 'project-manager', 'daily standup', '每日站会', 'n.', 'A short daily meeting where team members share progress, plans, and blockers.', 'The daily standup was capped at fifteen minutes to keep it focused.', '每日站会被限定在十五分钟以内，以保持聚焦。', ARRAY['agile', 'communication']::text[], null, null, 225, true),
  ('pm-definition-of-done', 'project-manager', 'definition of done', '完成的定义', 'n.', 'A shared checklist of criteria a task must meet to be considered complete.', 'A feature without automated tests didn''t meet the team''s definition of done.', '没有自动化测试的功能不符合团队完成的定义。', ARRAY['agile', 'quality']::text[], null, null, 226, true),
  ('pm-definition-of-ready', 'project-manager', 'definition of ready', '准备就绪的定义', 'n.', 'The criteria a backlog item must meet before it can be pulled into a sprint.', 'The story failed the definition of ready because it had no acceptance criteria.', '这个用户故事因为没有验收标准而未通过准备就绪的定义检查。', ARRAY['agile', 'requirements']::text[], null, null, 227, true),
  ('pm-story-point', 'project-manager', 'story point', '故事点', 'n.', 'A relative unit of measure used to estimate the effort required for a user story.', 'The team estimated the login redesign at five story points.', '团队把登录页面重设计估算为五个故事点。', ARRAY['agile', 'planning']::text[], null, null, 228, true),
  ('pm-velocity', 'project-manager', 'velocity', '速度（团队产出速率）', 'n.', 'The amount of work a team completes on average during a sprint, measured in story points.', 'Velocity dropped after two engineers went on vacation the same week.', '两名工程师同一周休假之后，团队速度有所下降。', ARRAY['agile', 'metrics']::text[], null, null, 229, true),
  ('pm-burndown-chart', 'project-manager', 'burndown chart', '燃尽图', 'n.', 'A chart that tracks remaining work against time during a sprint.', 'The burndown chart showed the team was on pace to finish early.', '燃尽图显示团队有望提前完成任务。', ARRAY['agile', 'metrics']::text[], null, null, 230, true),
  ('pm-burnup-chart', 'project-manager', 'burnup chart', '燃起图', 'n.', 'A chart that tracks completed work and total scope over time.', 'The burnup chart made scope creep visible in a way the burndown chart didn''t.', '燃起图能清楚地显示范围蔓延，而燃尽图做不到这一点。', ARRAY['agile', 'metrics']::text[], null, null, 231, true),
  ('pm-kanban-board', 'project-manager', 'Kanban board', '看板', 'n.', 'A visual board that shows work items moving through stages such as To Do, Doing, and Done.', 'The Kanban board made it obvious that too many tasks were stuck in review.', '看板清楚地显示出有太多任务卡在了评审环节。', ARRAY['agile', 'planning']::text[], null, null, 232, true),
  ('pm-work-in-progress-limit', 'project-manager', 'work in progress limit', '在制品限制', 'n.', 'A cap on the number of items allowed in a given stage of a workflow at one time.', 'Lowering the work in progress limit forced the team to finish tasks before starting new ones.', '降低在制品限制迫使团队先完成任务再开始新的工作。', ARRAY['agile', 'planning']::text[], null, null, 233, true),
  ('pm-scrum-of-scrums', 'project-manager', 'Scrum of Scrums', '多团队协同会议', 'n.', 'A coordination meeting between representatives of multiple Scrum teams working on related work.', 'Scrum of Scrums surfaced a shared dependency between the mobile and backend teams.', '多团队协同会议发现了移动端和后端团队之间的一个共同依赖。', ARRAY['agile', 'communication']::text[], null, null, 234, true),
  ('pm-agile-manifesto', 'project-manager', 'Agile manifesto', '敏捷宣言', 'n.', 'A foundational document outlining the values and principles behind Agile software development.', 'The Agile manifesto emphasizes individuals and interactions over processes and tools.', '敏捷宣言强调个体和互动胜过流程和工具。', ARRAY['agile', 'planning']::text[], null, null, 235, true),
  ('pm-self-organizing-team', 'project-manager', 'self-organizing team', '自组织团队', 'n.', 'A team that decides how to organize and accomplish its own work without external direction.', 'As a self-organizing team, they decided their own task assignments each sprint.', '作为一个自组织团队，他们每个迭代都自行决定任务分工。', ARRAY['agile', 'team']::text[], null, null, 236, true),
  ('pm-incremental-delivery', 'project-manager', 'incremental delivery', '增量交付', 'n.', 'Delivering a product in small, usable pieces rather than all at once.', 'Incremental delivery let users start benefiting from the tool months before full launch.', '增量交付让用户在完整上线前的几个月就能开始受益于这个工具。', ARRAY['agile', 'delivery']::text[], null, null, 237, true),
  ('pm-iterative-development', 'project-manager', 'iterative development', '迭代式开发', 'n.', 'Building a product through repeated cycles, refining it based on feedback each time.', 'Iterative development let us course-correct after the first round of user testing.', '迭代式开发让我们能在第一轮用户测试之后及时调整方向。', ARRAY['agile', 'lifecycle']::text[], null, null, 238, true),
  ('pm-planning-poker', 'project-manager', 'planning poker', '计划扑克', 'n.', 'An estimation technique where team members privately vote on effort using numbered cards.', 'Planning poker exposed a big disagreement about how complex the migration really was.', '计划扑克揭示出团队对迁移工作真实复杂度的巨大分歧。', ARRAY['agile', 'planning']::text[], null, null, 239, true),
  ('pm-technical-spike', 'project-manager', 'technical spike', '技术探针（技术调研任务）', 'n.', 'A short, time-boxed investigation to reduce uncertainty about a technical approach.', 'We ran a technical spike before committing to the new database engine.', '在决定采用新的数据库引擎之前，我们先进行了一次技术探针调研。', ARRAY['agile', 'technical']::text[], null, null, 240, true),
  ('pm-grooming-session', 'project-manager', 'grooming session', '梳理会议', 'n.', 'A meeting focused on clarifying, estimating, and detailing upcoming backlog items.', 'The grooming session split one oversized story into three smaller ones.', '梳理会议把一个过大的用户故事拆分成了三个更小的故事。', ARRAY['agile', 'planning']::text[], null, null, 241, true),
  ('pm-sprint-goal', 'project-manager', 'sprint goal', '迭代目标', 'n.', 'A short statement describing what the team aims to achieve by the end of a sprint.', 'The sprint goal was to ship a working checkout flow, even if not fully polished.', '这个迭代的目标是上线一个可用的结账流程，即使还不够完善。', ARRAY['agile', 'planning']::text[], null, null, 242, true),
  ('pm-timebox', 'project-manager', 'timebox', '限时', 'v.', 'To set a fixed maximum duration for an activity or event.', 'We timeboxed the debate over naming conventions to twenty minutes.', '我们把关于命名规范的讨论限时在二十分钟以内。', ARRAY['agile', 'planning']::text[], null, null, 243, true),
  ('pm-scrum-board', 'project-manager', 'Scrum board', 'Scrum 任务板', 'n.', 'A visual board used by a Scrum team to track sprint tasks and their status.', 'Every card on the Scrum board had an owner and a due date.', 'Scrum 任务板上的每张卡片都有一个负责人和一个截止日期。', ARRAY['agile', 'planning']::text[], null, null, 244, true),
  ('pm-user-story-mapping', 'project-manager', 'user story mapping', '用户故事地图', 'n.', 'A technique for visually organizing user stories along a user''s journey.', 'User story mapping revealed a gap in the onboarding flow nobody had noticed.', '用户故事地图揭示出新手引导流程中一个此前无人注意到的缺口。', ARRAY['agile', 'requirements']::text[], null, null, 245, true),
  ('pm-release-train', 'project-manager', 'release train', '发布火车', 'n.', 'A recurring, fixed schedule on which multiple teams synchronize their releases.', 'Missing the release train meant waiting another two weeks for the next one.', '错过这趟发布火车就意味着要再等两周才有下一趟。', ARRAY['agile', 'delivery']::text[], null, null, 246, true),
  ('pm-product-increment', 'project-manager', 'product increment', '产品增量', 'n.', 'A usable, potentially shippable piece of a product produced during a sprint.', 'Every sprint had to end with a working product increment, not just code.', '每个迭代都必须以一个可运行的产品增量结束，而不只是代码。', ARRAY['agile', 'delivery']::text[], null, null, 247, true),
  ('pm-scrum-ceremony', 'project-manager', 'Scrum ceremony', 'Scrum 仪式（活动）', 'n.', 'One of the formal, recurring events in the Scrum framework, such as sprint planning.', 'Skipping the Scrum ceremony for retrospectives meant problems kept repeating.', '跳过回顾会议这个 Scrum 仪式，导致问题一再重复出现。', ARRAY['agile', 'planning']::text[], null, null, 248, true),
  ('pm-kanban-cadence', 'project-manager', 'Kanban cadence', '看板节奏', 'n.', 'The regular rhythm at which a Kanban team reviews and replenishes its board.', 'The team''s Kanban cadence included a replenishment meeting every Monday.', '团队的看板节奏包括每周一的补充会议。', ARRAY['agile', 'planning']::text[], null, null, 249, true),
  ('pm-cumulative-flow-diagram', 'project-manager', 'cumulative flow diagram', '累积流图', 'n.', 'A chart showing the amount of work in each stage of a workflow over time.', 'The cumulative flow diagram showed work piling up in the code review stage.', '累积流图显示工作正在代码评审环节大量积压。', ARRAY['agile', 'metrics']::text[], null, null, 250, true),
  ('pm-agile-coach', 'project-manager', 'Agile coach', '敏捷教练', 'n.', 'A role that guides teams and organizations in adopting and improving Agile practices.', 'The Agile coach helped the team move from biweekly to weekly sprints.', '敏捷教练帮助团队把迭代周期从两周一次改成了每周一次。', ARRAY['agile', 'workplace']::text[], null, null, 251, true),
  ('pm-servant-leadership', 'project-manager', 'servant leadership', '服务型领导', 'n.', 'A leadership style focused on supporting and enabling the team rather than directing it.', 'Servant leadership meant the Scrum master''s job was to clear obstacles, not assign tasks.', '服务型领导意味着 Scrum 主管的职责是清除障碍，而不是分配任务。', ARRAY['agile', 'leadership']::text[], null, null, 252, true),
  ('pm-continuous-improvement', 'project-manager', 'continuous improvement', '持续改进', 'n.', 'The ongoing effort to incrementally improve processes, products, or services.', 'Continuous improvement turned small retrospective ideas into real process changes over time.', '持续改进让回顾会议上的小想法逐渐变成了真正的流程改变。', ARRAY['agile', 'quality']::text[], null, null, 253, true),
  ('pm-agile-transformation', 'project-manager', 'Agile transformation', '敏捷转型', 'n.', 'An organization-wide shift toward Agile values, principles, and practices.', 'The Agile transformation started with two pilot teams before rolling out company-wide.', '敏捷转型从两个试点团队开始，之后才在全公司推广。', ARRAY['agile', 'governance']::text[], null, null, 254, true),
  ('pm-quality-assurance', 'project-manager', 'quality assurance', '质量保证', 'n.', 'The systematic activities used to ensure a product meets defined quality standards.', 'Quality assurance caught the checkout bug before it ever reached customers.', '质量保证在结账问题触及客户之前就发现了它。', ARRAY['quality', 'delivery']::text[], null, null, 255, true),
  ('pm-quality-control', 'project-manager', 'quality control', '质量控制', 'n.', 'The process of inspecting deliverables to verify they meet quality requirements.', 'Quality control rejected the batch because three units failed the stress test.', '由于三个单元未能通过压力测试，质量控制拒绝了这批产品。', ARRAY['quality', 'delivery']::text[], null, null, 256, true),
  ('pm-quality-management-plan', 'project-manager', 'quality management plan', '质量管理计划', 'n.', 'A document describing how quality will be defined, measured, and controlled on a project.', 'The quality management plan set a maximum of two critical bugs per release.', '质量管理计划规定每次发布最多允许两个严重缺陷。', ARRAY['quality', 'planning']::text[], null, null, 257, true),
  ('pm-defect', 'project-manager', 'defect', '缺陷', 'n.', 'A flaw in a product that causes it to behave incorrectly or not meet requirements.', 'The defect only appeared when two features were used together.', '这个缺陷只有在同时使用两个功能时才会出现。', ARRAY['quality', 'delivery']::text[], null, null, 258, true),
  ('pm-defect-density', 'project-manager', 'defect density', '缺陷密度', 'n.', 'The number of defects found relative to the size of the software, such as per thousand lines.', 'Defect density dropped sharply after the team added automated code reviews.', '团队增加自动化代码评审后，缺陷密度大幅下降。', ARRAY['quality', 'metrics']::text[], null, null, 259, true),
  ('pm-user-acceptance-testing', 'project-manager', 'user acceptance testing', '用户验收测试', 'n.', 'Testing performed by end users to confirm a system meets their real-world needs.', 'User acceptance testing surfaced two workflow issues the internal team had missed.', '用户验收测试发现了两个内部团队没有注意到的流程问题。', ARRAY['quality', 'delivery']::text[], null, null, 260, true),
  ('pm-go-live', 'project-manager', 'go-live', '正式上线', 'n.', 'The point at which a system or product becomes available for real use.', 'Go-live was pushed back a day to fix a last-minute security issue.', '为了修复一个最后时刻发现的安全问题，正式上线推迟了一天。', ARRAY['delivery', 'lifecycle']::text[], null, null, 261, true),
  ('pm-release-plan', 'project-manager', 'release plan', '发布计划', 'n.', 'A document outlining what will be delivered, when, and how for a given release.', 'The release plan grouped three related features into the same version.', '发布计划把三个相关功能归入了同一个版本。', ARRAY['delivery', 'planning']::text[], null, null, 262, true),
  ('pm-release-notes', 'project-manager', 'release notes', '发布说明', 'n.', 'A document that summarizes changes, fixes, and new features in a release.', 'Customers appreciated release notes written in plain language instead of technical jargon.', '客户很欣赏用通俗语言而不是技术术语撰写的发布说明。', ARRAY['delivery', 'communication']::text[], null, null, 263, true),
  ('pm-rollback-plan', 'project-manager', 'rollback plan', '回滚计划', 'n.', 'A predefined procedure for reverting to a previous stable version if a release fails.', 'The rollback plan let us restore the old version within ten minutes of the failure.', '回滚计划让我们在故障发生后十分钟内就恢复了旧版本。', ARRAY['delivery', 'risk']::text[], null, null, 264, true),
  ('pm-deployment-window', 'project-manager', 'deployment window', '部署窗口', 'n.', 'A scheduled period of time during which a release is allowed to be deployed.', 'The deployment window was set for early Sunday morning to minimize user impact.', '部署窗口被安排在周日清晨，以尽量减少对用户的影响。', ARRAY['delivery', 'planning']::text[], null, null, 265, true),
  ('pm-hotfix', 'project-manager', 'hotfix', '紧急修复', 'n.', 'A quick, urgent fix applied to production to resolve a critical issue.', 'We shipped a hotfix within an hour of discovering the payment bug.', '发现支付问题后一小时内，我们就发布了紧急修复。', ARRAY['delivery', 'quality']::text[], null, null, 266, true),
  ('pm-regression-testing', 'project-manager', 'regression testing', '回归测试', 'n.', 'Re-running tests to confirm that new changes haven''t broken existing functionality.', 'Regression testing caught a bug in the login flow caused by an unrelated change.', '回归测试发现了一个由不相关改动引起的登录流程 bug。', ARRAY['quality', 'delivery']::text[], null, null, 267, true),
  ('pm-quality-gate', 'project-manager', 'quality gate', '质量门禁', 'n.', 'A checkpoint that code or a deliverable must pass before moving to the next stage.', 'The build failed the quality gate because test coverage dropped below eighty percent.', '由于测试覆盖率跌破了 80%，这次构建未能通过质量门禁。', ARRAY['quality', 'delivery']::text[], null, null, 268, true),
  ('pm-quality-metrics', 'project-manager', 'quality metrics', '质量指标', 'n.', 'Quantitative measures used to track and evaluate product or process quality.', 'Quality metrics included defect count, test coverage, and customer-reported issues.', '质量指标包括缺陷数量、测试覆盖率和客户报告的问题数。', ARRAY['quality', 'metrics']::text[], null, null, 269, true),
  ('pm-continuous-integration', 'project-manager', 'continuous integration', '持续集成', 'n.', 'The practice of frequently merging and automatically testing code changes.', 'Continuous integration flagged the broken build within minutes of the commit.', '持续集成在提交后几分钟内就标记出了这次构建失败。', ARRAY['quality', 'delivery']::text[], null, null, 270, true),
  ('pm-continuous-delivery', 'project-manager', 'continuous delivery', '持续交付', 'n.', 'The practice of keeping code always in a releasable state through automated pipelines.', 'Continuous delivery meant we could ship a fix the same day it was written.', '持续交付让我们能在修复代码写完的当天就完成发布。', ARRAY['delivery', 'agile']::text[], null, null, 271, true),
  ('pm-staging-environment', 'project-manager', 'staging environment', '预发布环境', 'n.', 'A pre-production environment used to test a release before it goes live.', 'The bug only showed up in the staging environment, never in local testing.', '这个 bug 只在预发布环境中出现，本地测试时从未发生。', ARRAY['delivery', 'quality']::text[], null, null, 272, true),
  ('pm-production-environment', 'project-manager', 'production environment', '生产环境', 'n.', 'The live environment where a system is actually used by real customers.', 'No code goes to the production environment without passing every quality gate first.', '任何代码在通过所有质量门禁之前，都不会进入生产环境。', ARRAY['delivery', 'quality']::text[], null, null, 273, true),
  ('pm-smoke-testing', 'project-manager', 'smoke testing', '冒烟测试', 'n.', 'A quick set of tests to verify the most critical functions work after a build or release.', 'Smoke testing after deployment confirmed login and checkout both still worked.', '部署后的冒烟测试确认了登录和结账功能都仍然正常。', ARRAY['quality', 'delivery']::text[], null, null, 274, true),
  ('pm-release-candidate', 'project-manager', 'release candidate', '发布候选版本', 'n.', 'A build that is potentially ready for release, pending final testing.', 'The release candidate passed every test except one edge case on older devices.', '这个发布候选版本除了在旧设备上有一个边界情况外，通过了所有测试。', ARRAY['delivery', 'quality']::text[], null, null, 275, true),
  ('pm-feature-flag', 'project-manager', 'feature flag', '功能开关', 'n.', 'A mechanism to turn a feature on or off without deploying new code.', 'A feature flag let us disable the new search instantly when it started erroring.', '功能开关让我们在新搜索功能开始报错时能立即将其关闭。', ARRAY['delivery', 'technical']::text[], null, null, 276, true),
  ('pm-quality-bar', 'project-manager', 'quality bar', '质量标准线', 'n.', 'The minimum acceptable level of quality a deliverable must meet.', 'The quality bar for this release was stricter because it touched the payment system.', '由于这次发布涉及支付系统，质量标准线定得更严格。', ARRAY['quality', 'planning']::text[], null, null, 277, true),
  ('pm-post-release-review', 'project-manager', 'post-release review', '发布后复盘', 'n.', 'A review held after a release to evaluate what went well and what didn''t.', 'The post-release review revealed the deployment checklist was missing a key step.', '发布后复盘发现部署清单遗漏了一个关键步骤。', ARRAY['delivery', 'quality']::text[], null, null, 278, true),
  ('pm-incident-report', 'project-manager', 'incident report', '事故报告', 'n.', 'A document describing what happened during a service disruption and how it was resolved.', 'The incident report detailed the outage timeline down to the minute.', '事故报告详细记录了这次中断的时间线，精确到分钟。', ARRAY['quality', 'governance']::text[], null, null, 279, true),
  ('pm-service-level-agreement', 'project-manager', 'service level agreement', '服务级别协议', 'n.', 'A contract that defines the expected level of service, such as uptime or response time.', 'The service level agreement guaranteed 99.9 percent uptime.', '服务级别协议保证了 99.9% 的正常运行时间。', ARRAY['delivery', 'procurement']::text[], null, null, 280, true),
  ('pm-warranty-period', 'project-manager', 'warranty period', '保修期', 'n.', 'A defined period after delivery during which defects are fixed at no extra cost.', 'The vendor fixed the bug free of charge because it was still within the warranty period.', '由于仍在保修期内，供应商免费修复了这个 bug。', ARRAY['delivery', 'procurement']::text[], null, null, 281, true),
  ('pm-delivery-confidence', 'project-manager', 'delivery confidence', '交付信心', 'n.', 'The team''s level of certainty that a deliverable will be ready on time and meet quality standards.', 'Delivery confidence dropped after two engineers called in sick during the final week.', '在最后一周有两名工程师请病假之后，交付信心有所下降。', ARRAY['delivery', 'planning']::text[], null, null, 282, true),
  ('pm-shippable-increment', 'project-manager', 'shippable increment', '可交付增量', 'n.', 'A piece of work that is complete enough to be released if the business chooses to.', 'Every sprint produced a shippable increment, even if we didn''t release it right away.', '每个迭代都会产出一个可交付增量，即使我们没有立即发布它。', ARRAY['delivery', 'agile']::text[], null, null, 283, true),
  ('pm-release-readiness-review', 'project-manager', 'release readiness review', '发布就绪评审', 'n.', 'A formal check to confirm a release meets all criteria before going live.', 'The release readiness review caught an outdated privacy policy link.', '发布就绪评审发现了一个过期的隐私政策链接。', ARRAY['delivery', 'quality']::text[], null, null, 284, true),
  ('pm-defect-triage', 'project-manager', 'defect triage', '缺陷分诊', 'n.', 'The process of reviewing and prioritizing reported defects for resolution.', 'Defect triage every morning decided which bugs got fixed before the next release.', '每天早上的缺陷分诊决定了哪些 bug 会在下次发布前被修复。', ARRAY['quality', 'planning']::text[], null, null, 285, true),
  ('pm-quality-audit', 'project-manager', 'quality audit', '质量审计', 'n.', 'An independent review to verify that quality processes are being followed correctly.', 'The quality audit found that code reviews were being skipped under deadline pressure.', '质量审计发现在截止日期压力下代码评审被跳过了。', ARRAY['quality', 'governance']::text[], null, null, 286, true),
  ('pm-customer-acceptance', 'project-manager', 'customer acceptance', '客户验收', 'n.', 'The formal confirmation from a customer that delivered work meets their requirements.', 'Customer acceptance was delayed until the reporting module was retested.', '在报告模块重新测试之前，客户验收被延后了。', ARRAY['quality', 'delivery']::text[], null, null, 287, true),
  ('pm-rollout-plan', 'project-manager', 'rollout plan', '推广计划', 'n.', 'A plan describing how a new product or feature will be gradually released to users.', 'The rollout plan started with five percent of users before expanding to everyone.', '推广计划从 5% 的用户开始，之后再扩展到所有人。', ARRAY['delivery', 'planning']::text[], null, null, 288, true),
  ('pm-beta-testing', 'project-manager', 'beta testing', '公测（内测）', 'n.', 'Testing a near-final product with a limited group of real users before general release.', 'Beta testing with twenty customers surfaced usability issues the team hadn''t noticed.', '与二十位客户进行的公测发现了团队没有注意到的可用性问题。', ARRAY['quality', 'delivery']::text[], null, null, 289, true),
  ('pm-vendor-management', 'project-manager', 'vendor management', '供应商管理', 'n.', 'The process of overseeing relationships and performance with external suppliers.', 'Vendor management improved after we assigned one person to own each key relationship.', '在为每个关键关系指定专人负责后，供应商管理有了改善。', ARRAY['procurement', 'workplace']::text[], null, null, 290, true),
  ('pm-procurement-plan', 'project-manager', 'procurement plan', '采购计划', 'n.', 'A document describing what will be purchased, from whom, and on what timeline.', 'The procurement plan listed three vendors to evaluate for the new licensing deal.', '采购计划列出了三家需要评估的供应商，以确定新的许可协议。', ARRAY['procurement', 'planning']::text[], null, null, 291, true),
  ('pm-request-for-proposal', 'project-manager', 'request for proposal', '征求建议书', 'n.', 'A formal document inviting vendors to submit proposals for a project or service.', 'We sent the request for proposal to five vendors and received three responses.', '我们向五家供应商发出了征求建议书，收到了三份回复。', ARRAY['procurement', 'planning']::text[], null, null, 292, true),
  ('pm-request-for-quotation', 'project-manager', 'request for quotation', '询价单', 'n.', 'A document asking vendors to provide pricing for specific goods or services.', 'The request for quotation asked for pricing on both hardware and installation.', '这份询价单要求供应商同时提供硬件和安装的报价。', ARRAY['procurement', 'planning']::text[], null, null, 293, true),
  ('pm-statement-of-work', 'project-manager', 'statement of work', '工作说明书', 'n.', 'A document that details the specific tasks, deliverables, and timeline a vendor will provide.', 'The statement of work spelled out exactly what was and wasn''t included in the contract.', '工作说明书详细说明了合同中包含和不包含的具体内容。', ARRAY['procurement', 'planning']::text[], null, null, 294, true),
  ('pm-master-service-agreement', 'project-manager', 'master service agreement', '主服务协议', 'n.', 'An overarching contract that sets terms for future work between two parties.', 'The master service agreement let us add new projects without renegotiating legal terms each time.', '主服务协议让我们能够增加新项目，而无需每次重新谈判法律条款。', ARRAY['procurement', 'governance']::text[], null, null, 295, true),
  ('pm-contract-negotiation', 'project-manager', 'contract negotiation', '合同谈判', 'n.', 'The process of discussing and agreeing on the terms of a contract.', 'Contract negotiation stalled over who would own the intellectual property.', '合同谈判在知识产权归属问题上陷入了僵局。', ARRAY['procurement', 'communication']::text[], null, null, 296, true),
  ('pm-purchase-order', 'project-manager', 'purchase order', '采购订单', 'n.', 'A formal document authorizing a purchase from a vendor at agreed terms.', 'No vendor could invoice us without an approved purchase order on file.', '没有备案的已批准采购订单，任何供应商都无法向我们开具发票。', ARRAY['procurement', 'governance']::text[], null, null, 297, true),
  ('pm-vendor-evaluation', 'project-manager', 'vendor evaluation', '供应商评估', 'n.', 'The process of assessing potential vendors against defined criteria.', 'Vendor evaluation weighed price, reliability, and past client reviews equally.', '供应商评估对价格、可靠性和以往客户评价给予了同等权重。', ARRAY['procurement', 'planning']::text[], null, null, 298, true),
  ('pm-vendor-onboarding', 'project-manager', 'vendor onboarding', '供应商引入', 'n.', 'The process of setting up a new vendor to begin working with an organization.', 'Vendor onboarding included a security review before any data was shared.', '供应商引入流程包括在共享任何数据之前的安全审查。', ARRAY['procurement', 'planning']::text[], null, null, 299, true),
  ('pm-fixed-price-contract', 'project-manager', 'fixed-price contract', '固定价格合同', 'n.', 'A contract where the total price is set in advance, regardless of actual costs incurred.', 'The fixed-price contract protected us from cost overruns on the vendor''s side.', '固定价格合同让我们不必承担供应商一方的成本超支风险。', ARRAY['procurement', 'budget']::text[], null, null, 300, true),
  ('pm-time-and-materials-contract', 'project-manager', 'time and materials contract', '按工时和材料计费合同', 'n.', 'A contract where payment is based on actual hours worked and materials used.', 'The time and materials contract made sense since the scope wasn''t fully defined yet.', '由于范围尚未完全确定，采用工时和材料计费合同是合理的。', ARRAY['procurement', 'budget']::text[], null, null, 301, true),
  ('pm-cost-reimbursable-contract', 'project-manager', 'cost-reimbursable contract', '成本补偿合同', 'n.', 'A contract where the buyer reimburses the seller''s actual costs plus a fee.', 'The cost-reimbursable contract included a cap to limit our total exposure.', '这份成本补偿合同设有上限，以限制我们的总体风险敞口。', ARRAY['procurement', 'budget']::text[], null, null, 302, true),
  ('pm-procurement-lifecycle', 'project-manager', 'procurement lifecycle', '采购生命周期', 'n.', 'The full sequence of steps from identifying a need to closing out a vendor contract.', 'The procurement lifecycle took six weeks from request for proposal to signed contract.', '从征求建议书到签署合同，整个采购生命周期花了六周时间。', ARRAY['procurement', 'lifecycle']::text[], null, null, 303, true),
  ('pm-supplier-relationship', 'project-manager', 'supplier relationship', '供应商关系', 'n.', 'The ongoing working relationship between an organization and its suppliers.', 'A strong supplier relationship got us priority support during the outage.', '良好的供应商关系让我们在故障期间获得了优先支持。', ARRAY['procurement', 'workplace']::text[], null, null, 304, true),
  ('pm-contract-milestone', 'project-manager', 'contract milestone', '合同里程碑', 'n.', 'A key point in a contract tied to a specific deliverable or payment.', 'The vendor missed the first contract milestone, triggering a penalty clause.', '供应商错过了第一个合同里程碑，触发了违约金条款。', ARRAY['procurement', 'schedule']::text[], null, null, 305, true),
  ('pm-contract-closure', 'project-manager', 'contract closure', '合同结束', 'n.', 'The formal completion and settlement of all obligations under a contract.', 'Contract closure required a final invoice reconciliation with the vendor.', '合同结束需要与供应商进行最终的发票核对。', ARRAY['procurement', 'lifecycle']::text[], null, null, 306, true),
  ('pm-non-disclosure-agreement', 'project-manager', 'non-disclosure agreement', '保密协议', 'n.', 'A legal contract that protects confidential information shared between parties.', 'We couldn''t share the roadmap until the vendor signed a non-disclosure agreement.', '在供应商签署保密协议之前，我们无法分享路线图。', ARRAY['procurement', 'governance']::text[], null, null, 307, true),
  ('pm-vendor-performance-review', 'project-manager', 'vendor performance review', '供应商绩效评审', 'n.', 'A periodic assessment of how well a vendor is meeting contractual expectations.', 'The quarterly vendor performance review flagged declining response times.', '季度供应商绩效评审标记出了响应时间正在下降的问题。', ARRAY['procurement', 'metrics']::text[], null, null, 308, true),
  ('pm-outsourcing', 'project-manager', 'outsourcing', '外包', 'n.', 'Contracting work to an external party instead of doing it in-house.', 'Outsourcing customer support let the core team focus on the product.', '将客户支持外包让核心团队能够专注于产品本身。', ARRAY['procurement', 'planning']::text[], null, null, 309, true),
  ('pm-subcontractor', 'project-manager', 'subcontractor', '分包商', 'n.', 'A company or individual hired by a primary contractor to perform specific work.', 'The subcontractor handled the electrical work under the main vendor''s contract.', '分包商在主承包商的合同框架下负责电气工作。', ARRAY['procurement', 'workplace']::text[], null, null, 310, true),
  ('pm-vendor-lock-in', 'project-manager', 'vendor lock-in', '供应商锁定', 'n.', 'A situation where switching away from a vendor becomes costly or impractical.', 'Vendor lock-in was a real concern before we chose a proprietary data format.', '在选择专有数据格式之前，供应商锁定确实是一个值得担心的问题。', ARRAY['procurement', 'risk']::text[], null, null, 311, true),
  ('pm-bid-evaluation', 'project-manager', 'bid evaluation', '投标评估', 'n.', 'The process of comparing and scoring vendor bids against defined criteria.', 'Bid evaluation ranked the three proposals on cost, timeline, and technical fit.', '投标评估从成本、进度和技术契合度三个维度对三份提案进行了排名。', ARRAY['procurement', 'planning']::text[], null, null, 312, true),
  ('pm-sourcing-strategy', 'project-manager', 'sourcing strategy', '寻源策略', 'n.', 'A plan for how and where an organization will obtain goods or services.', 'Our sourcing strategy favored local vendors to reduce shipping delays.', '我们的寻源策略倾向于选择本地供应商，以减少运输延误。', ARRAY['procurement', 'planning']::text[], null, null, 313, true),
  ('pm-procurement-risk', 'project-manager', 'procurement risk', '采购风险', 'n.', 'The risk that procurement activities will fail to deliver on cost, quality, or schedule.', 'Single-vendor procurement risk pushed us to qualify a backup supplier.', '单一供应商带来的采购风险促使我们认证了一家备用供应商。', ARRAY['procurement', 'risk']::text[], null, null, 314, true),
  ('pm-contract-compliance', 'project-manager', 'contract compliance', '合同合规', 'n.', 'Ensuring that all parties adhere to the terms specified in a contract.', 'Contract compliance audits confirmed the vendor met the agreed security standards.', '合同合规审计确认了供应商符合约定的安全标准。', ARRAY['procurement', 'governance']::text[], null, null, 315, true),
  ('pm-penalty-clause', 'project-manager', 'penalty clause', '违约金条款', 'n.', 'A contract term specifying a financial penalty for failing to meet obligations.', 'The penalty clause cost the vendor five percent of the contract value for the late delivery.', '违约金条款让供应商因交付延误而损失了合同金额的 5%。', ARRAY['procurement', 'governance']::text[], null, null, 316, true),
  ('pm-termination-clause', 'project-manager', 'termination clause', '终止条款', 'n.', 'A contract term specifying the conditions under which the agreement can be ended early.', 'The termination clause allowed us to exit with thirty days'' notice.', '终止条款允许我们提前三十天通知后退出合同。', ARRAY['procurement', 'governance']::text[], null, null, 317, true),
  ('pm-scope-of-work', 'project-manager', 'scope of work', '工作范围', 'n.', 'A detailed description of the specific work a vendor is contracted to perform.', 'Anything beyond the scope of work required a separate change order.', '任何超出工作范围的内容都需要单独的变更单。', ARRAY['procurement', 'planning']::text[], null, null, 318, true),
  ('pm-vendor-escalation', 'project-manager', 'vendor escalation', '供应商问题上报', 'n.', 'Raising an unresolved vendor issue to a higher level of authority on either side.', 'Vendor escalation to their account manager finally got the bug prioritized.', '向供应商的客户经理进行的问题上报，终于让这个 bug 被列为优先事项。', ARRAY['procurement', 'risk']::text[], null, null, 319, true),
  ('pm-third-party-dependency', 'project-manager', 'third-party dependency', '第三方依赖', 'n.', 'Reliance on an external vendor or system for part of a project''s functionality.', 'The outage exposed a critical third-party dependency we hadn''t documented.', '这次故障暴露出一个我们此前没有记录的关键第三方依赖。', ARRAY['procurement', 'risk']::text[], null, null, 320, true),
  ('pm-procurement-approval', 'project-manager', 'procurement approval', '采购审批', 'n.', 'The formal authorization required before a purchase can proceed.', 'Procurement approval took longer than expected because it exceeded the department''s spending limit.', '由于超出了部门的支出限额，采购审批花的时间比预期长。', ARRAY['procurement', 'governance']::text[], null, null, 321, true),
  ('pm-single-source-vendor', 'project-manager', 'single-source vendor', '单一来源供应商', 'n.', 'A vendor selected without competitive bidding, often due to unique capabilities.', 'We justified the single-source vendor because they were the only certified provider.', '由于他们是唯一获得认证的服务商，我们对选择单一来源供应商做出了说明。', ARRAY['procurement', 'risk']::text[], null, null, 322, true),
  ('pm-preferred-vendor', 'project-manager', 'preferred vendor', '优选供应商', 'n.', 'A vendor an organization favors due to a track record of reliable performance.', 'The preferred vendor list made it faster to get new contracts approved.', '优选供应商名单让新合同的审批速度更快了。', ARRAY['procurement', 'governance']::text[], null, null, 323, true),
  ('pm-contract-renewal', 'project-manager', 'contract renewal', '合同续签', 'n.', 'The process of extending or renewing a contract with a vendor before it expires.', 'We started contract renewal talks three months before the current agreement expired.', '我们在当前协议到期前三个月就开始了合同续签的谈判。', ARRAY['procurement', 'lifecycle']::text[], null, null, 324, true),
  ('pm-key-performance-indicator', 'project-manager', 'key performance indicator', '关键绩效指标', 'n.', 'A measurable value used to track how effectively a project is achieving its objectives.', 'On-time delivery rate was the key performance indicator the whole team was judged on.', '准时交付率是整个团队被考核的关键绩效指标。', ARRAY['metrics', 'governance']::text[], null, null, 325, true),
  ('pm-objectives-and-key-results', 'project-manager', 'objectives and key results', '目标与关键成果', 'n.', 'A goal-setting framework that pairs a qualitative objective with measurable key results.', 'Our objectives and key results for the quarter tied directly to this project''s success.', '我们这个季度的目标与关键成果直接与这个项目的成功挂钩。', ARRAY['metrics', 'planning']::text[], null, null, 326, true),
  ('pm-status-dashboard', 'project-manager', 'status dashboard', '状态看板', 'n.', 'A visual tool showing the current health of a project across key dimensions.', 'The status dashboard turned red the moment the schedule variance exceeded ten percent.', '一旦进度偏差超过 10%，状态看板就会变成红色。', ARRAY['metrics', 'communication']::text[], null, null, 327, true),
  ('pm-project-health-check', 'project-manager', 'project health check', '项目健康度检查', 'n.', 'A periodic assessment of a project''s overall status across scope, schedule, budget, and risk.', 'The monthly project health check gave leadership an honest view beyond the status report.', '每月的项目健康度检查为管理层提供了比状态报告更真实的视角。', ARRAY['metrics', 'governance']::text[], null, null, 328, true),
  ('pm-rag-status', 'project-manager', 'RAG status', '红黄绿状态', 'n.', 'A simple color-coded indicator (red, amber, green) showing whether a project is on track.', 'The project moved from green to amber RAG status after the vendor delay.', '由于供应商延误，项目的红黄绿状态从绿色变成了黄色。', ARRAY['metrics', 'communication']::text[], null, null, 329, true),
  ('pm-variance-report', 'project-manager', 'variance report', '偏差报告', 'n.', 'A report comparing planned versus actual performance for cost, schedule, or scope.', 'The variance report showed the budget was five percent over plan.', '偏差报告显示预算超出计划 5%。', ARRAY['metrics', 'governance']::text[], null, null, 330, true),
  ('pm-governance-board', 'project-manager', 'governance board', '治理委员会', 'n.', 'A group responsible for oversight, policy, and major decisions across projects.', 'The governance board reviewed every project with a budget over one million dollars.', '治理委员会审查了每一个预算超过一百万美元的项目。', ARRAY['governance', 'stakeholder']::text[], null, null, 331, true),
  ('pm-audit-trail', 'project-manager', 'audit trail', '审计轨迹', 'n.', 'A chronological record of actions and decisions that can be reviewed later.', 'The audit trail showed exactly when and by whom the budget was approved.', '审计轨迹清楚地显示了预算是何时、由谁批准的。', ARRAY['governance', 'metrics']::text[], null, null, 332, true),
  ('pm-compliance-requirement', 'project-manager', 'compliance requirement', '合规要求', 'n.', 'A rule or standard a project must satisfy due to law, regulation, or policy.', 'The compliance requirement for data residency shaped which cloud region we used.', '数据驻留方面的合规要求决定了我们使用哪个云区域。', ARRAY['governance', 'requirements']::text[], null, null, 333, true),
  ('pm-project-scorecard', 'project-manager', 'project scorecard', '项目记分卡', 'n.', 'A summary tool that rates a project across multiple weighted performance dimensions.', 'The project scorecard combined schedule, budget, and quality into a single grade.', '项目记分卡把进度、预算和质量综合成了一个单一评分。', ARRAY['metrics', 'governance']::text[], null, null, 334, true),
  ('pm-benefits-realization', 'project-manager', 'benefits realization', '效益实现', 'n.', 'The process of tracking whether a project actually delivers its intended business value.', 'Benefits realization was measured six months after go-live, not just at launch.', '效益实现是在正式上线六个月后才进行衡量的，而不是仅在上线时。', ARRAY['metrics', 'governance']::text[], null, null, 335, true),
  ('pm-milestone-tracking', 'project-manager', 'milestone tracking', '里程碑跟踪', 'n.', 'The ongoing process of monitoring whether planned milestones are met on schedule.', 'Milestone tracking flagged the design review as two weeks behind.', '里程碑跟踪发现设计评审已经延后了两周。', ARRAY['metrics', 'schedule']::text[], null, null, 336, true),
  ('pm-performance-baseline', 'project-manager', 'performance baseline', '绩效基准', 'n.', 'The approved reference point used to measure a project''s actual performance.', 'Every report compared current progress against the performance baseline.', '每份报告都会将当前进度与绩效基准进行对比。', ARRAY['metrics', 'governance']::text[], null, null, 337, true),
  ('pm-reporting-cadence', 'project-manager', 'reporting cadence', '汇报节奏', 'n.', 'The regular frequency at which project status is reported to stakeholders.', 'We increased the reporting cadence to twice a week during the final month.', '在最后一个月，我们把汇报节奏提高到了每周两次。', ARRAY['governance', 'communication']::text[], null, null, 338, true),
  ('pm-trend-analysis', 'project-manager', 'trend analysis', '趋势分析', 'n.', 'Examining data over time to identify patterns that inform future decisions.', 'Trend analysis showed defect counts rising steadily over the last three sprints.', '趋势分析显示过去三个迭代中缺陷数量持续上升。', ARRAY['metrics', 'quality']::text[], null, null, 339, true),
  ('pm-data-driven-decision-making', 'project-manager', 'data-driven decision making', '数据驱动决策', 'n.', 'Making choices based on data analysis rather than intuition alone.', 'Data-driven decision making led us to cut a feature almost nobody used.', '数据驱动决策促使我们砍掉了一个几乎没人使用的功能。', ARRAY['metrics', 'decision']::text[], null, null, 340, true),
  ('pm-project-maturity-model', 'project-manager', 'project maturity model', '项目成熟度模型', 'n.', 'A framework for assessing how developed and consistent an organization''s project practices are.', 'The project maturity model rated our estimating practices as the weakest area.', '项目成熟度模型将我们的估算实践评为最薄弱的环节。', ARRAY['governance', 'metrics']::text[], null, null, 341, true),
  ('pm-governance-framework', 'project-manager', 'governance framework', '治理框架', 'n.', 'The overall structure of policies, roles, and processes used to govern projects.', 'The new governance framework required sign-off from finance for any budget change.', '新的治理框架要求任何预算变更都需要财务部门的签字确认。', ARRAY['governance', 'planning']::text[], null, null, 342, true),
  ('pm-decision-rights', 'project-manager', 'decision rights', '决策权', 'n.', 'The defined authority specifying who is allowed to make which decisions.', 'Unclear decision rights led to the same choice being made twice by two different people.', '决策权不清晰导致同一个决定被两个不同的人分别做了一次。', ARRAY['governance', 'decision']::text[], null, null, 343, true),
  ('pm-forecast-accuracy', 'project-manager', 'forecast accuracy', '预测准确性', 'n.', 'How closely a project''s forecasts for cost, schedule, or scope match actual outcomes.', 'Forecast accuracy improved once we started using three-point estimates.', '自从我们开始使用三点估算法后，预测准确性有所提高。', ARRAY['metrics', 'governance']::text[], null, null, 344, true),
  ('pm-project-audit', 'project-manager', 'project audit', '项目审计', 'n.', 'An independent examination of a project to assess its health and adherence to standards.', 'The project audit recommended tightening the change control process.', '项目审计建议收紧变更控制流程。', ARRAY['governance', 'quality']::text[], null, null, 345, true),
  ('pm-cycle-time', 'project-manager', 'cycle time', '周期时间', 'n.', 'The total time it takes for a work item to move from start to completion.', 'Cycle time dropped from ten days to four after we removed an unnecessary approval step.', '在取消一个不必要的审批环节后，周期时间从十天缩短到了四天。', ARRAY['metrics', 'agile']::text[], null, null, 346, true),
  ('pm-throughput', 'project-manager', 'throughput', '吞吐量', 'n.', 'The number of work items a team completes within a given period.', 'Throughput increased once the team stopped context-switching between projects.', '在团队停止在多个项目之间来回切换之后，吞吐量提高了。', ARRAY['metrics', 'agile']::text[], null, null, 347, true),
  ('pm-flow-efficiency', 'project-manager', 'flow efficiency', '流动效率', 'n.', 'The ratio of active working time to total time a task spends in the workflow.', 'Flow efficiency was low because tasks spent most of their time waiting for review.', '流动效率很低，因为任务大部分时间都在等待评审。', ARRAY['metrics', 'agile']::text[], null, null, 348, true),
  ('pm-capacity-report', 'project-manager', 'capacity report', '产能报告', 'n.', 'A report showing a team''s available versus committed work capacity.', 'The capacity report showed the team was already booked at 120 percent for next month.', '产能报告显示团队下个月的排期已经达到了 120%。', ARRAY['metrics', 'resources']::text[], null, null, 349, true),
  ('pm-utilization-report', 'project-manager', 'utilization report', '利用率报告', 'n.', 'A report showing how much of available resource capacity is actually being used.', 'The utilization report revealed one team was consistently underused.', '利用率报告显示有一个团队一直处于利用不足的状态。', ARRAY['metrics', 'resources']::text[], null, null, 350, true),
  ('pm-milestone-report', 'project-manager', 'milestone report', '里程碑报告', 'n.', 'A report summarizing the status of upcoming and completed project milestones.', 'The milestone report was the first thing the sponsor read every Monday.', '里程碑报告是发起人每周一最先阅读的内容。', ARRAY['metrics', 'communication']::text[], null, null, 351, true),
  ('pm-exception-report', 'project-manager', 'exception report', '例外报告', 'n.', 'A report that highlights only items falling outside expected performance thresholds.', 'The exception report listed only the three tasks that had slipped their deadlines.', '例外报告只列出了三项错过截止日期的任务。', ARRAY['metrics', 'governance']::text[], null, null, 352, true),
  ('pm-red-flag-issue', 'project-manager', 'red flag issue', '红旗问题', 'n.', 'A serious issue that requires immediate attention from leadership.', 'The vendor''s missed milestone was flagged as a red flag issue in this week''s report.', '供应商错过里程碑在本周报告中被标记为红旗问题。', ARRAY['risk', 'communication']::text[], null, null, 353, true),
  ('pm-traffic-light-report', 'project-manager', 'traffic light report', '红绿灯报告', 'n.', 'A status report using color coding to quickly convey project health.', 'The traffic light report let executives scan ten projects in under a minute.', '红绿灯报告让高管能在一分钟内浏览完十个项目的状态。', ARRAY['metrics', 'communication']::text[], null, null, 354, true),
  ('pm-steering-cadence', 'project-manager', 'steering cadence', '指导委员会节奏', 'n.', 'The regular schedule on which a steering committee meets to review a project.', 'The steering cadence shifted from monthly to biweekly as the launch date approached.', '随着上线日期临近，指导委员会节奏从每月一次改成了每两周一次。', ARRAY['governance', 'communication']::text[], null, null, 355, true),
  ('pm-outcome-measurement', 'project-manager', 'outcome measurement', '成果衡量', 'n.', 'Assessing the real-world results a project produced, not just its outputs.', 'Outcome measurement focused on customer retention, not just feature completion.', '成果衡量关注的是客户留存率，而不仅仅是功能是否完成。', ARRAY['metrics', 'governance']::text[], null, null, 356, true),
  ('pm-post-mortem', 'project-manager', 'post-mortem', '复盘会议', 'n.', 'A review held after a project or incident to analyze what happened and why.', 'The post-mortem avoided blame and focused on fixing the process instead.', '复盘会议避免了追责，而是专注于修复流程本身。', ARRAY['governance', 'quality']::text[], null, null, 357, true),
  ('pm-baseline-comparison', 'project-manager', 'baseline comparison', '基准对比', 'n.', 'Comparing current project performance against its originally approved baseline.', 'Baseline comparison showed the budget baseline had already been revised twice.', '基准对比显示预算基准已经被修订过两次。', ARRAY['metrics', 'governance']::text[], null, null, 358, true),
  ('pm-project-performance-review', 'project-manager', 'project performance review', '项目绩效评审', 'n.', 'A formal evaluation of how well a project is meeting its goals.', 'The project performance review recommended adding a dedicated QA resource.', '项目绩效评审建议增加一名专职质量人员。', ARRAY['governance', 'metrics']::text[], null, null, 359, true),
  ('pm-meeting-agenda', 'project-manager', 'meeting agenda', '会议议程', 'n.', 'A list of topics to be discussed during a meeting, usually shared in advance.', 'A clear meeting agenda kept the discussion from drifting into unrelated topics.', '清晰的会议议程避免了讨论偏离到不相关的话题上。', ARRAY['communication', 'workplace']::text[], null, null, 360, true),
  ('pm-meeting-minutes', 'project-manager', 'meeting minutes', '会议纪要', 'n.', 'A written record of what was discussed and decided during a meeting.', 'The meeting minutes were sent out within an hour so nothing got forgotten.', '会议纪要在一小时内就发出了，避免了任何内容被遗忘。', ARRAY['communication', 'workplace']::text[], null, null, 361, true),
  ('pm-action-item', 'project-manager', 'action item', '行动项', 'n.', 'A specific task assigned to someone as a result of a meeting or discussion.', 'Every action item had an owner and a due date before the meeting ended.', '会议结束前，每一个行动项都明确了负责人和截止日期。', ARRAY['communication', 'workplace']::text[], null, null, 362, true),
  ('pm-working-session', 'project-manager', 'working session', '工作坊（工作会议）', 'n.', 'A focused meeting where participants actively produce a deliverable together.', 'The working session ended with a finished draft of the launch checklist.', '这次工作坊结束时，产出了一份完整的上线清单草案。', ARRAY['communication', 'workplace']::text[], null, null, 363, true),
  ('pm-facilitation', 'project-manager', 'facilitation', '引导（会议引导）', 'n.', 'The skill of guiding a group discussion to reach a productive outcome.', 'Good facilitation kept the workshop on track despite six strong opinions in the room.', '尽管现场有六种强烈的不同意见，良好的引导还是让工作坊保持在正轨上。', ARRAY['communication', 'leadership']::text[], null, null, 364, true),
  ('pm-negotiation-tactic', 'project-manager', 'negotiation tactic', '谈判策略', 'n.', 'A specific approach used to influence the outcome of a negotiation.', 'Anchoring high was the vendor''s opening negotiation tactic.', '开局报高价是供应商采用的谈判策略。', ARRAY['communication', 'negotiation']::text[], null, null, 365, true),
  ('pm-win-win-outcome', 'project-manager', 'win-win outcome', '双赢结果', 'n.', 'A resolution that satisfies the interests of all parties involved.', 'Extending the deadline by a week produced a win-win outcome for both teams.', '把截止日期延长一周，为双方团队带来了双赢结果。', ARRAY['negotiation', 'communication']::text[], null, null, 366, true),
  ('pm-batna', 'project-manager', 'BATNA', '谈判最佳替代方案', 'n.', 'The best alternative a party has if a negotiation fails to reach agreement.', 'Knowing our BATNA gave us the confidence to walk away from a bad vendor deal.', '清楚我们的谈判最佳替代方案，让我们有底气拒绝一份糟糕的供应商协议。', ARRAY['negotiation', 'communication']::text[], null, null, 367, true),
  ('pm-consensus-decision', 'project-manager', 'consensus decision', '共识决策', 'n.', 'A decision reached when all participants agree to support it, even without full enthusiasm.', 'It took an extra hour, but the team reached a consensus decision on the tech stack.', '虽然多花了一个小时，但团队最终就技术栈达成了共识决策。', ARRAY['decision', 'communication']::text[], null, null, 368, true),
  ('pm-brainstorming-session', 'project-manager', 'brainstorming session', '头脑风暴会议', 'n.', 'A meeting focused on generating a wide range of ideas without immediate judgment.', 'The brainstorming session produced fifteen ideas, three of which made the final shortlist.', '这次头脑风暴会议产出了十五个想法，其中三个进入了最终候选名单。', ARRAY['communication', 'workplace']::text[], null, null, 369, true),
  ('pm-workshop-facilitation', 'project-manager', 'workshop facilitation', '工作坊引导', 'n.', 'Guiding a structured group session to achieve a specific collaborative outcome.', 'Workshop facilitation kept twelve participants focused on one decision at a time.', '工作坊引导让十二名参与者每次专注于一个决策。', ARRAY['communication', 'leadership']::text[], null, null, 370, true),
  ('pm-parking-lot', 'project-manager', 'parking lot', '暂存区（会议延伸话题清单）', 'n.', 'A running list of off-topic ideas raised during a meeting to be addressed later.', 'The pricing question went into the parking lot so the meeting could stay focused.', '定价问题被放进了暂存区，以便会议能保持聚焦。', ARRAY['communication', 'workplace']::text[], null, null, 371, true),
  ('pm-round-robin-discussion', 'project-manager', 'round-robin discussion', '轮流发言讨论', 'n.', 'A discussion format where each participant speaks in turn to ensure everyone is heard.', 'A round-robin discussion made sure the quieter team members shared their concerns too.', '轮流发言讨论确保了性格内向的团队成员也能表达自己的担忧。', ARRAY['communication', 'workplace']::text[], null, null, 372, true),
  ('pm-meeting-cadence', 'project-manager', 'meeting cadence', '会议节奏', 'n.', 'The regular rhythm at which recurring meetings are held.', 'We reduced the meeting cadence from daily to twice a week once the crisis passed.', '危机过去后，我们把会议节奏从每天一次减少到了每周两次。', ARRAY['communication', 'planning']::text[], null, null, 373, true),
  ('pm-majority-vote', 'project-manager', 'majority vote', '多数表决', 'n.', 'A decision-making method where the option with the most votes is chosen.', 'The team settled the naming debate with a quick majority vote.', '团队通过一次简单的多数表决解决了命名争议。', ARRAY['decision', 'communication']::text[], null, null, 374, true),
  ('pm-cross-team-coordination', 'project-manager', 'cross-team coordination', '跨团队协调', 'n.', 'Aligning activities and schedules between separate teams working on related work.', 'Cross-team coordination prevented the mobile and web releases from conflicting.', '跨团队协调避免了移动端和网页端发布计划的冲突。', ARRAY['communication', 'collaboration']::text[], null, null, 375, true),
  ('pm-sync-meeting', 'project-manager', 'sync meeting', '同步会议', 'n.', 'A short meeting held to align two or more parties on current status.', 'A weekly sync meeting with the vendor kept both sides on the same page.', '每周与供应商的同步会议让双方保持信息一致。', ARRAY['communication', 'workplace']::text[], null, null, 376, true),
  ('pm-retrospective-facilitation', 'project-manager', 'retrospective facilitation', '回顾会议引导', 'n.', 'Guiding a retrospective meeting so the team openly discusses what to improve.', 'Retrospective facilitation by a neutral outsider helped the team be more honest.', '由中立的外部人员进行的回顾会议引导，帮助团队更加坦诚地交流。', ARRAY['communication', 'agile']::text[], null, null, 377, true),
  ('pm-negotiation-leverage', 'project-manager', 'negotiation leverage', '谈判筹码', 'n.', 'The relative power or advantage a party holds in a negotiation.', 'Having a second vendor lined up gave us real negotiation leverage on price.', '手上有备选的第二家供应商，让我们在价格谈判中有了真正的筹码。', ARRAY['negotiation', 'communication']::text[], null, null, 378, true),
  ('pm-ground-rules', 'project-manager', 'ground rules', '会议基本规则', 'n.', 'Agreed-upon norms of behavior for how a meeting or team will operate.', 'The ground rules included no phones and one person speaking at a time.', '会议基本规则包括不使用手机，以及一次只能有一个人发言。', ARRAY['communication', 'workplace']::text[], null, null, 379, true),
  ('pm-icebreaker', 'project-manager', 'icebreaker', '破冰活动', 'n.', 'A short activity used at the start of a meeting to help participants relax and connect.', 'A quick icebreaker helped the newly merged teams feel more comfortable together.', '一个简短的破冰活动帮助新合并的团队更快地熟络起来。', ARRAY['communication', 'workplace']::text[], null, null, 380, true),
  ('pm-meeting-facilitator', 'project-manager', 'meeting facilitator', '会议主持人', 'n.', 'The person responsible for guiding a meeting toward its intended outcome.', 'The meeting facilitator kept everyone to their two-minute time limit.', '会议主持人让每个人都遵守了两分钟的发言时限。', ARRAY['communication', 'leadership']::text[], null, null, 381, true),
  ('pm-virtual-meeting-etiquette', 'project-manager', 'virtual meeting etiquette', '线上会议礼仪', 'n.', 'Agreed norms of behavior for participating respectfully in online meetings.', 'Virtual meeting etiquette meant muting yourself when not speaking.', '线上会议礼仪要求不发言时保持静音。', ARRAY['communication', 'workplace']::text[], null, null, 382, true),
  ('pm-asynchronous-update', 'project-manager', 'asynchronous update', '异步更新', 'n.', 'A status update shared without requiring all participants to be present at the same time.', 'An asynchronous update in the shared doc replaced the need for a daily call across time zones.', '共享文档中的异步更新取代了跨时区每日通话的需要。', ARRAY['communication', 'workplace']::text[], null, null, 383, true),
  ('pm-huddle', 'project-manager', 'huddle', '简短碰头会', 'n.', 'A brief, informal gathering to quickly align on an urgent matter.', 'The team called a huddle the moment the production alert came in.', '生产环境警报一出现，团队就立刻召开了一次简短碰头会。', ARRAY['communication', 'workplace']::text[], null, null, 384, true),
  ('pm-war-room', 'project-manager', 'war room', '作战室（应急指挥室）', 'n.', 'A dedicated space or virtual channel used to coordinate response during a crisis.', 'The war room stayed active until the outage was fully resolved.', '作战室一直保持运转，直到这次故障被彻底解决。', ARRAY['communication', 'risk']::text[], null, null, 385, true),
  ('pm-debrief', 'project-manager', 'debrief', '情况汇报', 'n.', 'A short discussion after an event to review what happened and capture takeaways.', 'The debrief after the client demo focused on which slides landed well.', '客户演示后的情况汇报聚焦于哪些幻灯片效果最好。', ARRAY['communication', 'quality']::text[], null, null, 386, true),
  ('pm-pre-mortem', 'project-manager', 'pre-mortem', '事前验尸（预先失败分析）', 'n.', 'An exercise imagining a project has failed, to proactively identify potential causes.', 'The pre-mortem uncovered a staffing risk nobody had raised before.', '事前验尸分析发现了一个此前从未有人提出过的人员风险。', ARRAY['risk', 'planning']::text[], null, null, 387, true),
  ('pm-table-a-discussion', 'project-manager', 'table a discussion', '暂缓讨论', 'v.', 'To postpone discussion of a topic to a later time.', 'We agreed to table the naming discussion until after the demo.', '我们同意把命名讨论暂缓到演示结束之后再进行。', ARRAY['communication', 'workplace']::text[], null, null, 388, true),
  ('pm-counteroffer', 'project-manager', 'counteroffer', '反报价', 'n.', 'An alternative proposal made in response to an initial offer during a negotiation.', 'The vendor''s counteroffer was still ten percent above our budget.', '供应商的反报价仍然比我们的预算高出 10%。', ARRAY['negotiation', 'communication']::text[], null, null, 389, true),
  ('pm-compromise', 'project-manager', 'compromise', '妥协', 'n.', 'An agreement reached where each party gives up something to reach a resolution.', 'The compromise gave the client two of their three requested features.', '这次妥协让客户得到了他们要求的三个功能中的两个。', ARRAY['negotiation', 'communication']::text[], null, null, 390, true),
  ('pm-stakeholder-negotiation', 'project-manager', 'stakeholder negotiation', '干系人谈判', 'n.', 'Discussions aimed at reaching agreement with stakeholders on project terms or scope.', 'Stakeholder negotiation over the launch date ended with a two-week compromise.', '关于上线日期的干系人谈判最终以两周的折中方案收场。', ARRAY['negotiation', 'stakeholder']::text[], null, null, 391, true),
  ('pm-agenda-item', 'project-manager', 'agenda item', '议程项', 'n.', 'A single topic listed for discussion within a meeting agenda.', 'The budget review was the first agenda item, before anything else was discussed.', '预算审查是第一个议程项，排在其他讨论之前。', ARRAY['communication', 'workplace']::text[], null, null, 392, true),
  ('pm-quorum', 'project-manager', 'quorum', '法定人数', 'n.', 'The minimum number of participants required for a meeting or vote to be valid.', 'The steering committee couldn''t vote because they didn''t have quorum.', '由于未达到法定人数，指导委员会无法进行表决。', ARRAY['governance', 'communication']::text[], null, null, 393, true),
  ('pm-minutes-distribution', 'project-manager', 'minutes distribution', '会议纪要分发', 'n.', 'The process of sharing meeting minutes with all relevant stakeholders.', 'Minutes distribution went out to everyone, including those who missed the meeting.', '会议纪要分发发给了所有相关人员，包括缺席会议的人。', ARRAY['communication', 'governance']::text[], null, null, 394, true),
  ('pm-situational-leadership', 'project-manager', 'situational leadership', '情境领导', 'n.', 'Adapting one''s leadership style based on the specific needs of a team member or situation.', 'Situational leadership meant giving the new hire more guidance than the senior engineer.', '情境领导意味着给新员工的指导比给资深工程师的更多。', ARRAY['leadership', 'team']::text[], null, null, 395, true),
  ('pm-team-charter', 'project-manager', 'team charter', '团队章程', 'n.', 'A document that defines a team''s purpose, norms, and ways of working together.', 'The team charter set clear expectations for response time on messages.', '团队章程明确规定了消息回复时间的期望标准。', ARRAY['leadership', 'team']::text[], null, null, 396, true),
  ('pm-performance-feedback', 'project-manager', 'performance feedback', '绩效反馈', 'n.', 'Information given to an individual about how well they are meeting expectations.', 'Performance feedback was given monthly instead of saved up for an annual review.', '绩效反馈是每月给出的，而不是攒到年度评审时才给。', ARRAY['leadership', 'workplace']::text[], null, null, 397, true),
  ('pm-constructive-feedback', 'project-manager', 'constructive feedback', '建设性反馈', 'n.', 'Feedback intended to help someone improve, delivered in a supportive way.', 'Constructive feedback focused on the missed deadline, not on blaming any one person.', '建设性反馈聚焦于错过的截止日期本身，而不是指责某一个人。', ARRAY['leadership', 'communication']::text[], null, null, 398, true),
  ('pm-conflict-resolution', 'project-manager', 'conflict resolution', '冲突解决', 'n.', 'The process of resolving a disagreement between two or more parties.', 'Conflict resolution between the two leads took a neutral third party to mediate.', '两位负责人之间的冲突解决需要一名中立的第三方来调解。', ARRAY['leadership', 'communication']::text[], null, null, 399, true),
  ('pm-team-dynamics', 'project-manager', 'team dynamics', '团队动态', 'n.', 'The patterns of interaction, behavior, and relationships within a team.', 'Team dynamics improved noticeably after the difficult project ended.', '在那个艰难的项目结束之后，团队动态明显有了改善。', ARRAY['leadership', 'team']::text[], null, null, 400, true),
  ('pm-psychological-safety', 'project-manager', 'psychological safety', '心理安全感', 'n.', 'A shared belief that it is safe to take interpersonal risks, such as admitting mistakes.', 'Psychological safety let engineers report bugs without fear of being blamed.', '心理安全感让工程师们能够报告 bug 而不必担心被责怪。', ARRAY['leadership', 'team']::text[], null, null, 401, true),
  ('pm-team-morale', 'project-manager', 'team morale', '团队士气', 'n.', 'The overall level of enthusiasm and confidence within a team.', 'Team morale dropped after two consecutive missed deadlines.', '连续两次错过截止日期后，团队士气有所下降。', ARRAY['leadership', 'team']::text[], null, null, 402, true),
  ('pm-coaching-conversation', 'project-manager', 'coaching conversation', '辅导对话', 'n.', 'A structured, supportive discussion aimed at helping someone grow or solve a problem.', 'A coaching conversation helped the junior PM think through the stakeholder conflict himself.', '一次辅导对话帮助这位初级项目经理自己理清了干系人冲突的思路。', ARRAY['leadership', 'communication']::text[], null, null, 403, true),
  ('pm-delegation', 'project-manager', 'delegation', '授权', 'n.', 'Assigning responsibility and authority for a task to another person.', 'Delegation of the vendor relationship freed up the PM to focus on the roadmap.', '把供应商关系的管理授权出去，让项目经理能够专注于路线图。', ARRAY['leadership', 'workplace']::text[], null, null, 404, true),
  ('pm-accountability', 'project-manager', 'accountability', '责任担当', 'n.', 'Being answerable for one''s actions, decisions, and their outcomes.', 'Real accountability meant the team owned the missed deadline instead of blaming the vendor.', '真正的责任担当意味着团队为错过的截止日期负责，而不是归咎于供应商。', ARRAY['leadership', 'workplace']::text[], null, null, 405, true),
  ('pm-team-empowerment', 'project-manager', 'team empowerment', '团队赋能', 'n.', 'Giving a team the authority and confidence to make decisions on its own.', 'Team empowerment meant engineers could choose their own tools without approval.', '团队赋能意味着工程师可以自行选择工具，无需审批。', ARRAY['leadership', 'team']::text[], null, null, 406, true),
  ('pm-difficult-conversation', 'project-manager', 'difficult conversation', '艰难对话', 'n.', 'A conversation involving sensitive, uncomfortable, or high-stakes topics.', 'The difficult conversation about underperformance was overdue by two months.', '这场关于绩效不佳的艰难对话已经拖延了两个月。', ARRAY['leadership', 'communication']::text[], null, null, 407, true),
  ('pm-performance-improvement-plan', 'project-manager', 'performance improvement plan', '绩效改进计划', 'n.', 'A formal plan outlining specific steps an underperforming employee must take to improve.', 'The performance improvement plan gave clear, measurable goals over ninety days.', '绩效改进计划为九十天内的进步设定了清晰、可衡量的目标。', ARRAY['leadership', 'workplace']::text[], null, null, 408, true),
  ('pm-team-motivation', 'project-manager', 'team motivation', '团队激励', 'n.', 'The factors that drive a team''s energy, effort, and commitment toward its goals.', 'Team motivation stayed high because progress was visible every single week.', '由于每周都能看到明显的进展，团队激励一直保持在较高水平。', ARRAY['leadership', 'team']::text[], null, null, 409, true),
  ('pm-employee-recognition', 'project-manager', 'employee recognition', '员工认可', 'n.', 'Acknowledging and appreciating an individual''s contributions or achievements.', 'Public employee recognition during the town hall boosted morale across the department.', '在全员大会上公开进行的员工认可，提升了整个部门的士气。', ARRAY['leadership', 'workplace']::text[], null, null, 410, true),
  ('pm-mentorship', 'project-manager', 'mentorship', '导师制', 'n.', 'A relationship in which a more experienced person guides the development of a less experienced one.', 'Mentorship paired every new project manager with a senior one for their first six months.', '导师制为每位新任项目经理在头六个月安排了一位资深导师。', ARRAY['leadership', 'workplace']::text[], null, null, 411, true),
  ('pm-team-building', 'project-manager', 'team building', '团队建设', 'n.', 'Activities designed to improve cooperation and relationships within a team.', 'The team building offsite helped two previously separate teams start working as one.', '团队建设团建活动帮助两个原本各自独立的团队开始真正协作起来。', ARRAY['leadership', 'team']::text[], null, null, 412, true),
  ('pm-burnout', 'project-manager', 'burnout', '职业倦怠', 'n.', 'A state of physical and emotional exhaustion caused by prolonged stress at work.', 'Burnout on the team was a direct result of three consecutive crunch releases.', '团队的职业倦怠是连续三次高强度冲刺发布的直接后果。', ARRAY['leadership', 'risk']::text[], null, null, 413, true),
  ('pm-workload-balancing', 'project-manager', 'workload balancing', '工作量平衡', 'n.', 'Distributing tasks evenly across team members to avoid overload.', 'Workload balancing shifted two tasks from the busiest engineer to someone with more capacity.', '工作量平衡把两项任务从最忙碌的工程师那里转移给了产能更充裕的人。', ARRAY['leadership', 'resources']::text[], null, null, 414, true),
  ('pm-skip-level-meeting', 'project-manager', 'skip-level meeting', '越级会议', 'n.', 'A meeting between an employee and their manager''s manager.', 'The skip-level meeting surfaced concerns the team hadn''t felt comfortable raising directly.', '这次越级会议揭示出团队之前不敢直接提出的担忧。', ARRAY['leadership', 'communication']::text[], null, null, 415, true),
  ('pm-blameless-retrospective', 'project-manager', 'blameless retrospective', '无责难复盘', 'n.', 'A review process focused on learning from mistakes without assigning personal blame.', 'A blameless retrospective made engineers willing to share exactly what went wrong.', '无责难复盘让工程师们愿意坦诚地分享到底出了什么问题。', ARRAY['leadership', 'agile']::text[], null, null, 416, true),
  ('pm-feedback-sandwich', 'project-manager', 'feedback sandwich', '反馈三明治法', 'n.', 'A technique for delivering criticism between two pieces of positive feedback.', 'The feedback sandwich softened the message but sometimes made it less clear.', '反馈三明治法让批评听起来更委婉，但有时也会让信息不够明确。', ARRAY['leadership', 'communication']::text[], null, null, 417, true),
  ('pm-leadership-style', 'project-manager', 'leadership style', '领导风格', 'n.', 'The characteristic approach a person takes to guiding and motivating others.', 'Her leadership style was collaborative, always asking for input before deciding.', '她的领导风格偏向协作型，总是在决定之前先征求大家的意见。', ARRAY['leadership', 'team']::text[], null, null, 418, true),
  ('pm-trust-building', 'project-manager', 'trust building', '建立信任', 'n.', 'Actions taken to develop mutual confidence and reliability between people.', 'Trust building with the new vendor started with small, low-risk deliverables.', '与新供应商建立信任是从一些风险较低的小型交付物开始的。', ARRAY['leadership', 'stakeholder']::text[], null, null, 419, true),
  ('pm-team-resilience', 'project-manager', 'team resilience', '团队韧性', 'n.', 'A team''s ability to recover quickly from setbacks and keep moving forward.', 'Team resilience was tested when the launch had to be rebuilt from scratch overnight.', '当上线方案不得不连夜重做时，团队韧性经受住了考验。', ARRAY['leadership', 'team']::text[], null, null, 420, true),
  ('pm-conflict-de-escalation', 'project-manager', 'conflict de-escalation', '冲突降级', 'n.', 'Actions taken to reduce the intensity of a disagreement before it worsens.', 'Conflict de-escalation in the meeting kept a heated debate from turning personal.', '会议中的冲突降级避免了一场激烈的争论演变成人身攻击。', ARRAY['leadership', 'communication']::text[], null, null, 421, true),
  ('pm-peer-feedback', 'project-manager', 'peer feedback', '同侪反馈', 'n.', 'Feedback given between colleagues at the same level rather than from a manager.', 'Peer feedback during the retrospective was often more candid than manager feedback.', '回顾会议中的同侪反馈往往比来自管理者的反馈更加坦诚。', ARRAY['leadership', 'communication']::text[], null, null, 422, true),
  ('pm-role-clarity', 'project-manager', 'role clarity', '角色清晰度', 'n.', 'A clear, shared understanding of who is responsible for what within a team.', 'Role clarity improved once we documented who owned each part of the release process.', '在我们把发布流程每个环节的负责人写清楚之后，角色清晰度有了改善。', ARRAY['leadership', 'team']::text[], null, null, 423, true),
  ('pm-empathetic-leadership', 'project-manager', 'empathetic leadership', '共情式领导', 'n.', 'A leadership approach that prioritizes understanding and responding to team members'' feelings and needs.', 'Empathetic leadership meant checking in on workload before assigning anything new.', '共情式领导意味着在分配新任务之前，先了解大家当前的工作量。', ARRAY['leadership', 'team']::text[], null, null, 424, true),
  ('pm-growth-mindset', 'project-manager', 'growth mindset', '成长型思维', 'n.', 'The belief that abilities can be developed through effort and learning.', 'A growth mindset helped the team treat the failed launch as a learning opportunity.', '成长型思维让团队把这次失败的上线当作一次学习的机会。', ARRAY['leadership', 'team']::text[], null, null, 425, true),
  ('pm-underperformance', 'project-manager', 'underperformance', '绩效不佳', 'n.', 'Work output that falls below expected standards.', 'Underperformance on the vendor''s side led us to invoke the penalty clause.', '供应商一方的绩效不佳促使我们启用了违约金条款。', ARRAY['leadership', 'risk']::text[], null, null, 426, true),
  ('pm-team-retention', 'project-manager', 'team retention', '团队留存', 'n.', 'The ability to keep skilled team members from leaving over time.', 'Team retention improved after we gave engineers more ownership over technical decisions.', '在给予工程师更多技术决策的自主权之后，团队留存有所提升。', ARRAY['leadership', 'workplace']::text[], null, null, 427, true),
  ('pm-succession-planning', 'project-manager', 'succession planning', '继任规划', 'n.', 'Preparing to fill key roles in advance in case the current person leaves.', 'Succession planning meant a backup lead was already trained before the transition happened.', '继任规划意味着在交接发生之前，备用负责人早已完成培训。', ARRAY['leadership', 'governance']::text[], null, null, 428, true),
  ('pm-leading-by-example', 'project-manager', 'leading by example', '以身作则', 'v. phr.', 'Demonstrating desired behavior through one''s own actions rather than just instructions.', 'Leading by example, the manager was the first to admit her own mistake in the retrospective.', '以身作则，这位经理在回顾会议上第一个承认了自己的失误。', ARRAY['leadership', 'team']::text[], null, null, 429, true),
  ('pm-cross-functional-team', 'project-manager', 'cross-functional team', '跨职能团队', 'n.', 'A team made up of members with different functional expertise working toward a shared goal.', 'The cross-functional team included engineers, designers, and a marketer from day one.', '这个跨职能团队从一开始就包括了工程师、设计师和一名市场人员。', ARRAY['collaboration', 'team']::text[], null, null, 430, true),
  ('pm-engineering-handoff', 'project-manager', 'engineering handoff', '工程交接', 'n.', 'The transfer of a finished design or requirement from one team to engineering for implementation.', 'The engineering handoff went smoothly because the designs already included edge cases.', '由于设计稿中已经包含了边界情况，这次工程交接进行得很顺利。', ARRAY['collaboration', 'technical']::text[], null, null, 431, true),
  ('pm-technical-feasibility', 'project-manager', 'technical feasibility', '技术可行性', 'n.', 'An assessment of whether a proposed solution can realistically be built with available technology.', 'Technical feasibility ruled out real-time syncing within the current budget.', '技术可行性评估排除了在当前预算内实现实时同步的可能性。', ARRAY['collaboration', 'technical']::text[], null, null, 432, true),
  ('pm-product-engineering-alignment', 'project-manager', 'product-engineering alignment', '产品与工程对齐', 'n.', 'Shared agreement between product and engineering teams on priorities and trade-offs.', 'Product-engineering alignment prevented the team from building a feature nobody asked for.', '产品与工程对齐避免了团队开发出一个没人要求的功能。', ARRAY['collaboration', 'technical']::text[], null, null, 433, true),
  ('pm-dependency-coordination', 'project-manager', 'dependency coordination', '依赖协调', 'n.', 'Actively managing cross-team dependencies so they don''t block progress.', 'Dependency coordination between three teams kept the API changes from breaking the app.', '三个团队之间的依赖协调避免了 API 变更破坏应用。', ARRAY['collaboration', 'schedule']::text[], null, null, 434, true),
  ('pm-integration-handoff', 'project-manager', 'integration handoff', '集成交接', 'n.', 'The point at which one team''s work is passed to another team to be connected with theirs.', 'The integration handoff between the payments team and the checkout team happened a week early.', '支付团队和结账团队之间的集成交接提前了一周完成。', ARRAY['collaboration', 'technical']::text[], null, null, 435, true),
  ('pm-design-to-development-handoff', 'project-manager', 'design-to-development handoff', '设计到开发交接', 'n.', 'The process of transferring finalized designs to developers for implementation.', 'A clean design-to-development handoff meant fewer questions during the sprint.', '干净利落的设计到开发交接，让这个迭代中的疑问少了很多。', ARRAY['collaboration', 'technical']::text[], null, null, 436, true),
  ('pm-cross-team-dependency', 'project-manager', 'cross-team dependency', '跨团队依赖', 'n.', 'A situation where one team''s progress relies on the output of another team.', 'The cross-team dependency on the platform team delayed the feature by a sprint.', '对平台团队的跨团队依赖让这个功能延误了一个迭代。', ARRAY['collaboration', 'risk']::text[], null, null, 437, true),
  ('pm-shared-roadmap', 'project-manager', 'shared roadmap', '共享路线图', 'n.', 'A single roadmap visible to and agreed upon by multiple teams.', 'A shared roadmap kept the marketing and engineering launch dates in sync.', '共享路线图让市场团队和工程团队的上线日期保持了一致。', ARRAY['collaboration', 'planning']::text[], null, null, 438, true),
  ('pm-technical-constraint', 'project-manager', 'technical constraint', '技术约束', 'n.', 'A limitation imposed by existing systems, infrastructure, or technology choices.', 'A technical constraint in the legacy database ruled out real-time reporting.', '遗留数据库的技术约束排除了实现实时报表的可能性。', ARRAY['collaboration', 'technical']::text[], null, null, 439, true),
  ('pm-non-technical-stakeholder', 'project-manager', 'non-technical stakeholder', '非技术干系人', 'n.', 'A stakeholder without a technical background who still has interest or influence in a project.', 'We translated the architecture diagram into plain language for the non-technical stakeholder.', '我们把架构图翻译成通俗语言，给非技术干系人讲解。', ARRAY['collaboration', 'stakeholder']::text[], null, null, 440, true),
  ('pm-requirement-translation', 'project-manager', 'requirement translation', '需求转译', 'n.', 'Converting business needs into language and specifications engineers can act on.', 'Requirement translation turned a vague request into three clear technical tasks.', '需求转译把一个模糊的要求变成了三个清晰的技术任务。', ARRAY['collaboration', 'requirements']::text[], null, null, 441, true),
  ('pm-engineering-estimate', 'project-manager', 'engineering estimate', '工程估算', 'n.', 'An engineer''s assessment of how long a technical task will take to complete.', 'The engineering estimate came in twice as high as the initial guess.', '工程估算的结果是最初猜测的两倍。', ARRAY['collaboration', 'schedule']::text[], null, null, 442, true),
  ('pm-team-capacity', 'project-manager', 'team capacity', '团队产能', 'n.', 'The amount of work a specific team can realistically take on in a given period.', 'Team capacity for next sprint was reduced because two engineers were on call.', '由于有两名工程师需要值班，下个迭代的团队产能有所减少。', ARRAY['collaboration', 'resources']::text[], null, null, 443, true),
  ('pm-joint-planning-session', 'project-manager', 'joint planning session', '联合规划会议', 'n.', 'A planning meeting involving representatives from multiple teams.', 'The joint planning session aligned the backend and frontend teams on the same API contract.', '这次联合规划会议让后端和前端团队就同一份 API 约定达成了一致。', ARRAY['collaboration', 'planning']::text[], null, null, 444, true),
  ('pm-embedded-project-manager', 'project-manager', 'embedded project manager', '嵌入式项目经理', 'n.', 'A project manager who works directly within a technical team rather than externally.', 'The embedded project manager attended every standup with the engineering team.', '嵌入式项目经理参加了工程团队的每一次站会。', ARRAY['collaboration', 'workplace']::text[], null, null, 445, true),
  ('pm-matrix-organization', 'project-manager', 'matrix organization', '矩阵型组织', 'n.', 'An organizational structure where employees report to both a functional and a project manager.', 'In a matrix organization, the designer reported to both the design lead and the project manager.', '在矩阵型组织中，这名设计师同时向设计负责人和项目经理汇报。', ARRAY['collaboration', 'governance']::text[], null, null, 446, true),
  ('pm-functional-manager', 'project-manager', 'functional manager', '职能经理', 'n.', 'A manager responsible for a specific department or discipline, such as engineering.', 'The functional manager approved which engineers could be assigned to the project.', '职能经理批准了哪些工程师可以被分配到这个项目。', ARRAY['collaboration', 'workplace']::text[], null, null, 447, true),
  ('pm-dotted-line-reporting', 'project-manager', 'dotted-line reporting', '虚线汇报关系', 'n.', 'A secondary, informal reporting relationship alongside an employee''s primary manager.', 'The analyst had a dotted-line reporting relationship to the project manager during the initiative.', '在这个项目期间，这名分析师与项目经理之间存在虚线汇报关系。', ARRAY['collaboration', 'governance']::text[], null, null, 448, true),
  ('pm-shared-ownership', 'project-manager', 'shared ownership', '共同所有权', 'n.', 'A situation where multiple people or teams are jointly responsible for an outcome.', 'Shared ownership of the API meant both teams reviewed every change to it.', '对这个 API 的共同所有权意味着两个团队都会评审每一次改动。', ARRAY['collaboration', 'team']::text[], null, null, 449, true),
  ('pm-technical-liaison', 'project-manager', 'technical liaison', '技术联络人', 'n.', 'A person who serves as the communication link between a technical team and other groups.', 'The technical liaison translated engineering blockers into terms the client could understand.', '技术联络人把工程方面的阻碍转化成了客户能理解的语言。', ARRAY['collaboration', 'communication']::text[], null, null, 450, true),
  ('pm-architecture-review', 'project-manager', 'architecture review', '架构评审', 'n.', 'A formal evaluation of a proposed technical design before it is built.', 'The architecture review caught a scalability issue before any code was written.', '架构评审在任何代码写出来之前就发现了一个可扩展性问题。', ARRAY['collaboration', 'technical']::text[], null, null, 451, true),
  ('pm-proof-of-concept', 'project-manager', 'proof of concept', '概念验证', 'n.', 'A small-scale implementation used to demonstrate that an idea is technically viable.', 'The proof of concept confirmed the new approach could handle the expected traffic.', '概念验证证实了新方案能够应对预期的流量。', ARRAY['collaboration', 'technical']::text[], null, null, 452, true),
  ('pm-pilot-program', 'project-manager', 'pilot program', '试点项目', 'n.', 'A small-scale trial run of an initiative before a full rollout.', 'The pilot program with one team revealed process gaps before we scaled to the whole company.', '在一个团队进行的试点项目在我们推广到全公司之前，暴露出了流程上的漏洞。', ARRAY['collaboration', 'planning']::text[], null, null, 453, true),
  ('pm-alignment-workshop', 'project-manager', 'alignment workshop', '对齐工作坊', 'n.', 'A working session designed to get multiple teams or stakeholders on the same page.', 'The alignment workshop resolved a months-long disagreement about ownership boundaries.', '这场对齐工作坊解决了持续数月的关于职责边界的分歧。', ARRAY['collaboration', 'communication']::text[], null, null, 454, true),
  ('pm-platform-team', 'project-manager', 'platform team', '平台团队', 'n.', 'A team that builds and maintains shared infrastructure or tools used by other teams.', 'The platform team''s new deployment tool cut release time in half for every product team.', '平台团队的新部署工具让每个产品团队的发布时间都缩短了一半。', ARRAY['collaboration', 'technical']::text[], null, null, 455, true),
  ('pm-shared-services-team', 'project-manager', 'shared services team', '共享服务团队', 'n.', 'A team that provides common support functions, such as QA or DevOps, to multiple projects.', 'Requests to the shared services team had to be submitted a week in advance.', '向共享服务团队提出的请求需要提前一周提交。', ARRAY['collaboration', 'workplace']::text[], null, null, 456, true),
  ('pm-dependency-owner', 'project-manager', 'dependency owner', '依赖责任人', 'n.', 'The person accountable for resolving a specific cross-team dependency.', 'Every dependency on the tracker had a named dependency owner, not just a team name.', '追踪表中的每一项依赖都有一个明确的依赖责任人，而不只是一个团队名称。', ARRAY['collaboration', 'governance']::text[], null, null, 457, true),
  ('pm-integration-point', 'project-manager', 'integration point', '集成点', 'n.', 'A specific place where two systems or components connect and exchange data.', 'The integration point between the CRM and the billing system caused most of the delays.', 'CRM 系统和计费系统之间的集成点是造成大部分延误的原因。', ARRAY['collaboration', 'technical']::text[], null, null, 458, true),
  ('pm-release-coordination', 'project-manager', 'release coordination', '发布协调', 'n.', 'Aligning the release schedules and dependencies of multiple teams for a single launch.', 'Release coordination across four teams was tracked in a single shared checklist.', '四个团队之间的发布协调都记录在一份共享清单中。', ARRAY['collaboration', 'delivery']::text[], null, null, 459, true),
  ('pm-joint-accountability', 'project-manager', 'joint accountability', '共同问责', 'n.', 'A shared responsibility where multiple parties are held accountable for the same outcome.', 'Joint accountability between product and engineering meant neither team could blame the other.', '产品团队和工程团队之间的共同问责，让任何一方都无法把责任推给对方。', ARRAY['collaboration', 'leadership']::text[], null, null, 460, true),
  ('pm-co-located-team', 'project-manager', 'co-located team', '同地办公团队', 'n.', 'A team whose members work in the same physical location.', 'As a co-located team, they could resolve a design question in a five-minute hallway chat.', '作为一个同地办公团队，他们能通过五分钟的走廊闲聊解决一个设计问题。', ARRAY['collaboration', 'team']::text[], null, null, 461, true),
  ('pm-distributed-team', 'project-manager', 'distributed team', '分布式团队', 'n.', 'A team whose members work from different physical locations or time zones.', 'The distributed team relied heavily on written documentation to stay aligned.', '这个分布式团队非常依赖书面文档来保持信息同步。', ARRAY['collaboration', 'team']::text[], null, null, 462, true),
  ('pm-remote-collaboration', 'project-manager', 'remote collaboration', '远程协作', 'n.', 'Working together effectively across different physical locations using digital tools.', 'Remote collaboration improved once the team agreed on core working hours.', '在团队就核心工作时间达成一致之后，远程协作有了改善。', ARRAY['collaboration', 'workplace']::text[], null, null, 463, true),
  ('pm-hybrid-team', 'project-manager', 'hybrid team', '混合办公团队', 'n.', 'A team with some members working in an office and others working remotely.', 'The hybrid team scheduled key decisions for the days everyone was in the office.', '这个混合办公团队把关键决策安排在了大家都在办公室的日子。', ARRAY['collaboration', 'team']::text[], null, null, 464, true),
  ('pm-star-method', 'project-manager', 'STAR method', 'STAR 回答法', 'n.', 'A structured way to answer behavioral interview questions by describing Situation, Task, Action, and Result.', 'She used the STAR method to walk through how she recovered a failing project.', '她用 STAR 回答法讲述了自己是如何挽救一个陷入困境的项目的。', ARRAY['interview', 'communication']::text[], null, null, 465, true),
  ('pm-behavioral-interview-question', 'project-manager', 'behavioral interview question', '行为面试问题', 'n.', 'A question that asks candidates to describe how they handled a real past situation.', 'The behavioral interview question asked about a time she disagreed with a stakeholder.', '这道行为面试问题询问了她曾经与干系人意见不合的一次经历。', ARRAY['interview', 'communication']::text[], null, null, 466, true),
  ('pm-leadership-philosophy', 'project-manager', 'leadership philosophy', '领导理念', 'n.', 'A person''s core beliefs about how to guide and support a team.', 'His leadership philosophy centered on giving the team context, not just instructions.', '他的领导理念的核心是给团队提供背景信息，而不只是下达指令。', ARRAY['interview', 'leadership']::text[], null, null, 467, true),
  ('pm-career-transition', 'project-manager', 'career transition', '职业转型', 'n.', 'A significant change from one role, function, or industry to another.', 'Her career transition from engineering to project management gave her a technical edge.', '她从工程师转型为项目经理的职业转型，为她带来了技术方面的优势。', ARRAY['interview', 'workplace']::text[], null, null, 468, true),
  ('pm-pmp-certification', 'project-manager', 'PMP certification', 'PMP 认证', 'n.', 'A globally recognized professional certification for project managers.', 'Earning the PMP certification pushed him to formalize practices he''d been doing informally.', '获得 PMP 认证促使他把之前非正式的做法系统化了。', ARRAY['interview', 'workplace']::text[], null, null, 469, true),
  ('pm-situational-judgment', 'project-manager', 'situational judgment', '情境判断能力', 'n.', 'The ability to choose an effective course of action in a realistic workplace scenario.', 'The interview tested situational judgment with a scenario about a missed deadline.', '这次面试通过一个错过截止日期的场景来测试情境判断能力。', ARRAY['interview', 'decision']::text[], null, null, 470, true),
  ('pm-cross-industry-experience', 'project-manager', 'cross-industry experience', '跨行业经验', 'n.', 'Professional experience gained across more than one industry or sector.', 'Cross-industry experience in both healthcare and finance helped her spot risks others missed.', '同时拥有医疗和金融行业经验，让她能发现别人忽略的风险。', ARRAY['interview', 'workplace']::text[], null, null, 471, true),
  ('pm-project-highlights', 'project-manager', 'project highlights', '项目亮点', 'n.', 'The most notable or impressive achievements from a candidate''s past projects.', 'He led with his project highlights: a launch delivered two weeks early under budget.', '他首先讲述了自己的项目亮点：一次提前两周、且低于预算完成的上线。', ARRAY['interview', 'workplace']::text[], null, null, 472, true),
  ('pm-greatest-challenge', 'project-manager', 'greatest challenge', '最大挑战', 'n.', 'A common interview prompt asking a candidate to describe a significant difficulty they overcame.', 'Her greatest challenge story was about rebuilding trust after a failed vendor rollout.', '她讲述的最大挑战故事，是关于在一次失败的供应商上线之后重建信任的经历。', ARRAY['interview', 'workplace']::text[], null, null, 473, true),
  ('pm-failure-story', 'project-manager', 'failure story', '失败经历', 'n.', 'An honest account of a past mistake or setback and what was learned from it.', 'A good failure story shows self-awareness, not just what went wrong.', '一个好的失败经历不仅要讲清楚哪里出了问题，更要体现出自我认知。', ARRAY['interview', 'communication']::text[], null, null, 474, true),
  ('pm-strengths-and-weaknesses', 'project-manager', 'strengths and weaknesses', '优势与不足', 'n.', 'A candidate''s self-assessment of their key capabilities and areas for growth.', 'When asked about strengths and weaknesses, he gave a specific, recent example for each.', '在被问及优势与不足时，他为每一点都举出了一个具体的近期例子。', ARRAY['interview', 'communication']::text[], null, null, 475, true),
  ('pm-motivation-for-the-role', 'project-manager', 'motivation for the role', '应聘动机', 'n.', 'The reasons a candidate gives for wanting a specific job or company.', 'Her motivation for the role was clearly tied to the company''s mission, not just the salary.', '她的应聘动机明显与公司的使命相关，而不仅仅是薪资。', ARRAY['interview', 'workplace']::text[], null, null, 476, true),
  ('pm-salary-expectation', 'project-manager', 'salary expectation', '薪资期望', 'n.', 'The compensation range a candidate states they are seeking for a role.', 'He gave a salary expectation range instead of a single fixed number.', '他给出的是一个薪资期望区间，而不是一个固定数字。', ARRAY['interview', 'workplace']::text[], null, null, 477, true),
  ('pm-notice-period', 'project-manager', 'notice period', '离职通知期', 'n.', 'The amount of time an employee must work after resigning before officially leaving.', 'Her notice period at her current job was four weeks.', '她在现在这份工作的离职通知期是四周。', ARRAY['interview', 'workplace']::text[], null, null, 478, true),
  ('pm-management-style', 'project-manager', 'management style', '管理风格', 'n.', 'The characteristic way a person manages tasks, decisions, and people.', 'He described his management style as hands-off once trust had been established.', '他把自己的管理风格描述为一旦建立起信任，就会放手让团队自主。', ARRAY['interview', 'leadership']::text[], null, null, 479, true),
  ('pm-handling-ambiguity', 'project-manager', 'handling ambiguity', '应对不确定性', 'n.', 'The ability to make progress and decisions even when information is incomplete.', 'Handling ambiguity well meant she kept the team moving despite unclear requirements.', '善于应对不确定性，让她在需求不明确的情况下仍能推动团队向前。', ARRAY['interview', 'decision']::text[], null, null, 480, true),
  ('pm-handling-pressure', 'project-manager', 'handling pressure', '应对压力', 'n.', 'The ability to remain effective and composed under stressful conditions.', 'His story about handling pressure focused on staying calm during a production outage.', '他讲述的应对压力的故事，聚焦于生产环境故障期间如何保持冷静。', ARRAY['interview', 'workplace']::text[], null, null, 481, true),
  ('pm-prioritization-skills', 'project-manager', 'prioritization skills', '优先级排序能力', 'n.', 'The ability to determine which tasks or issues deserve attention first.', 'Strong prioritization skills let her cut a low-value feature without hesitation.', '出色的优先级排序能力，让她能毫不犹豫地砍掉一个低价值功能。', ARRAY['interview', 'planning']::text[], null, null, 482, true),
  ('pm-stakeholder-management-experience', 'project-manager', 'stakeholder management experience', '干系人管理经验', 'n.', 'A candidate''s track record of successfully working with people who have influence over a project.', 'His stakeholder management experience included handling a difficult executive sponsor.', '他的干系人管理经验包括应对一位比较难相处的高管发起人。', ARRAY['interview', 'stakeholder']::text[], null, null, 483, true),
  ('pm-team-leadership-example', 'project-manager', 'team leadership example', '团队领导案例', 'n.', 'A specific past instance a candidate uses to demonstrate their leadership ability.', 'She offered a team leadership example about turning around a demotivated team.', '她举出了一个团队领导案例，讲述了如何重新激活一个士气低落的团队。', ARRAY['interview', 'leadership']::text[], null, null, 484, true),
  ('pm-conflict-example', 'project-manager', 'conflict example', '冲突处理案例', 'n.', 'A specific past instance a candidate describes to show how they handle disagreement.', 'His conflict example described mediating between two engineers with opposing designs.', '他的冲突处理案例描述了如何在两名设计方案相左的工程师之间进行调解。', ARRAY['interview', 'leadership']::text[], null, null, 485, true),
  ('pm-decision-making-example', 'project-manager', 'decision-making example', '决策案例', 'n.', 'A specific past instance a candidate uses to illustrate their approach to making decisions.', 'Her decision-making example showed how she chose data over gut feeling.', '她的决策案例展示了她是如何选择依据数据而不是直觉做决定的。', ARRAY['interview', 'decision']::text[], null, null, 486, true),
  ('pm-measurable-impact', 'project-manager', 'measurable impact', '可衡量的影响', 'n.', 'A quantifiable result attributed to a candidate''s specific contribution.', 'He backed up every claim with measurable impact, like a 15 percent cost reduction.', '他为每一个说法都提供了可衡量的影响作为支撑，比如 15% 的成本削减。', ARRAY['interview', 'metrics']::text[], null, null, 487, true),
  ('pm-quantifiable-result', 'project-manager', 'quantifiable result', '量化成果', 'n.', 'A concrete, numeric outcome a candidate can point to as evidence of their work.', 'A quantifiable result, like reducing cycle time by a third, made her answer stand out.', '像把周期时间缩短三分之一这样的量化成果，让她的回答脱颖而出。', ARRAY['interview', 'metrics']::text[], null, null, 488, true),
  ('pm-self-introduction', 'project-manager', 'self-introduction', '自我介绍', 'n.', 'A brief opening statement a candidate gives to summarize their background and interests.', 'His self-introduction covered his background in under ninety seconds.', '他的自我介绍在不到九十秒的时间内就概括了自己的背景。', ARRAY['interview', 'communication']::text[], null, null, 489, true),
  ('pm-career-goal', 'project-manager', 'career goal', '职业目标', 'n.', 'A candidate''s stated ambition for their professional future.', 'Her career goal was to eventually lead a full portfolio of products, not just one project.', '她的职业目标是最终能够负责一整个产品组合，而不只是一个项目。', ARRAY['interview', 'workplace']::text[], null, null, 490, true),
  ('pm-professional-development', 'project-manager', 'professional development', '职业发展', 'n.', 'Ongoing learning and skill-building undertaken to advance one''s career.', 'He mentioned reading widely on Agile coaching as part of his professional development.', '他提到广泛阅读敏捷教练相关书籍是他职业发展的一部分。', ARRAY['interview', 'workplace']::text[], null, null, 491, true),
  ('pm-continuing-education', 'project-manager', 'continuing education', '继续教育', 'n.', 'Formal learning pursued after entering the workforce, such as courses or certifications.', 'Continuing education in data analysis rounded out her existing project management skills.', '在数据分析方面的继续教育，补全了她原有的项目管理技能。', ARRAY['interview', 'workplace']::text[], null, null, 492, true),
  ('pm-industry-certification', 'project-manager', 'industry certification', '行业认证', 'n.', 'A credential recognized within a specific field as evidence of expertise.', 'The industry certification wasn''t required, but it strengthened his application.', '这项行业认证虽非必需，但增强了他的申请材料的说服力。', ARRAY['interview', 'workplace']::text[], null, null, 493, true),
  ('pm-reference-check', 'project-manager', 'reference check', '背景调查（推荐人核实）', 'n.', 'The process of contacting a candidate''s former colleagues or managers to verify their history.', 'The reference check confirmed everything she had said about the failed launch.', '背景调查证实了她关于那次失败上线所说的一切。', ARRAY['interview', 'workplace']::text[], null, null, 494, true),
  ('pm-offer-negotiation', 'project-manager', 'offer negotiation', '录用条件谈判', 'n.', 'Discussions between a candidate and employer to finalize the terms of a job offer.', 'Offer negotiation focused more on the start date than the salary itself.', '录用条件谈判的重点更多集中在入职日期上，而不是薪资本身。', ARRAY['interview', 'negotiation']::text[], null, null, 495, true),
  ('pm-question-for-the-interviewer', 'project-manager', 'question for the interviewer', '给面试官的问题', 'n.', 'A question a candidate asks at the end of an interview to learn more or show interest.', 'Her question for the interviewer was about how the team handled scope changes.', '她给面试官的问题是关于团队如何处理范围变更的。', ARRAY['interview', 'communication']::text[], null, null, 496, true),
  ('pm-culture-fit', 'project-manager', 'culture fit', '文化契合度', 'n.', 'How well a candidate''s values and working style align with an organization''s culture.', 'The panel weighed culture fit alongside technical skills for this role.', '面试小组在评估这个职位时，把文化契合度和技术能力放在了同等重要的位置。', ARRAY['interview', 'workplace']::text[], null, null, 497, true),
  ('pm-30-60-90-day-plan', 'project-manager', '30-60-90 day plan', '入职 30-60-90 天计划', 'n.', 'A candidate''s outline of priorities for their first three months in a new role.', 'His 30-60-90 day plan started with listening before proposing any changes.', '他的入职 30-60-90 天计划从倾听开始，之后才提出任何变更建议。', ARRAY['interview', 'planning']::text[], null, null, 498, true),
  ('pm-closing-statement', 'project-manager', 'closing statement', '结束陈述', 'n.', 'A candidate''s final remarks summarizing their interest and fit before an interview ends.', 'Her closing statement reaffirmed why this specific project excited her.', '她的结束陈述再次强调了这个特定项目为什么让她感到兴奋。', ARRAY['interview', 'communication']::text[], null, null, 499, true);
